// Өгөгдлийн сан → ӨӨРИЙН VPS Postgres, PostgREST дамжуулан (Caddy /db → PostgREST).
// ⚠ Нэршил: эдгээр тогтмол урьд нь SUPABASE_URL/SUPABASE_ANON_KEY нэртэй байсан ч Supabase
// cloud-той ямар ч хамааралгүй (2026-06-28-нд VPS рүү бүрэн шилжсэн). Нэр нь төөрөгдүүлж
// байсан тул DB_URL/DB_ANON_KEY болгов (2026-08-30). anon JWT нь PUBLIC — frontend-д ил
// байх нь зөв, эмзэг хүснэгтийг RLS-ээр хамгаална.
const DB_URL = 'https://n8n.nomaadcamp.com/db';
const DB_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYW5vbiJ9.Brx7AjnPrzfv--KLb-J-FK-7DmdRusxUF2jaFgKzd1s';   // VPS PostgREST anon JWT (role=anon, PUBLIC/frontend-safe)
// Барааны зураг VPS дээр (n8n.nomaadcamp.com/img/<file>) — mevent-upload-image webhook-оор
// байршуулна (uploadProductImage). Гуравдагч талын storage ашиглахаа больсон.
// URL рүү ?key= эсвэл &key= нэмж буцаана. n8n workflow эхэнд IF node-оор тулгаж шалгана.
function withKey(url) {
  if (!url) return url;
  const sep = url.includes('?') ? '&' : '?';
  return `${url}${sep}key=${encodeURIComponent(N8N_API_KEY)}`;
}
// Нэвтэрсэн хэрэглэгчийн PostgREST JWT (role=authenticated, эрх/түвшин шингэсэн) — эмзэг хүснэгтийн
// бичилтэд anon-ы оронд ашиглана. DB талд RLS шалгана. Байхгүй бол anon руу уналт (RLS унтраалттай
// хүснэгтэд ажиллах — пилот шилжилтийн үед эвдрэлгүй байлгах).
function pgrstToken() { try { return localStorage.getItem('pgrstToken') || ''; } catch (e) { return ''; } }
function pgrstBearer() { return pgrstToken() || DB_ANON_KEY; }
// PostgREST БИЧИХ (POST/PATCH/DELETE) header — нэвтэрсэн ажилтны токенээр (RLS түгжсэн хүснэгтэд).
// Токенгүй бол anon руу fallback (хуучин session → 403, дахин нэвтрэхэд засагдана).
function pgWrite(extra) { return Object.assign({ apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), 'Content-Type': 'application/json' }, extra || {}); }

// fetch timeout wrapper — кемп/3G гэх мэт сул сүлжээ үед fetch 60-120 сек ширж байж
// аппыг "гацсан" гэж мэдрүүлдэг. AbortController-аар хугацаа тавьж хурдан буцах.
// Default 15s ердийн дуудлагад; upload-д заавал тусдаа удаан хугацаа өг.
function fetchWithTimeout(url, opts = {}, timeoutMs = 15000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  return fetch(url, { ...opts, signal: ctrl.signal })
    .finally(() => clearTimeout(timer));
}

// Modal save товчинд хурдан 2 удаа дарахад давтан POST явахаас сэргийлнэ.
// async ажиллах хугацаанд товч disabled байж, дууссаны дараа (success/error аль аль)
// автомат буцаана. Хэрэв opts.successText өгсөн бол амжилт-н дараа товч 800мс ✓ текстээр
// flash хийгээд эх HTML рүү буцана — хэрэглэгчид click → action бэлэн боллоо гэдгийг
// шууд харуулна.
async function withBusy(btn, asyncFn, opts = {}) {
  if (!btn) return asyncFn();
  if (btn.disabled) return; // өмнөх дуудалт хараахан дуусаагүй
  btn.disabled = true;
  const origHTML = btn.innerHTML;
  let success = false;
  try {
    const result = await asyncFn();
    success = true;
    return result;
  } finally {
    if (success && opts.successText) {
      btn.innerHTML = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:4px;"><polyline points="20 6 9 17 4 12"/></svg>${opts.successText}`;
      await new Promise(r => setTimeout(r, 800));
    }
    btn.disabled = false;
    btn.innerHTML = origHTML;
  }
}
