    attendance: ['<svg class="lcd-icon" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M8 2v4M16 2v4M3 10h18"/></svg>', 'Ирц', 'QR-аар ирц бүртгэх — ажилчид утсаараа уншуулна'],
