          const hourlyEmp = (emp && emp.type === 'hourly' && _salaryMemo) ? emp : null;
          const cardL4 = detectCardLast4(r.memo);
          const depMatch = depositMatchForStmt(r.memo, r.debit);   // барьцаа буцаалт бол → захиалгад авто холбоно
