// Ажлын гарчиг — модал (давхардал таних) ба үүсгэхэд ИЖИЛ байх ёстой. Хугацаагүй бол хаалт нэмэхгүй.
function prepTaskTitle(c) { return `${c.group}: ${c.title}${c.deadline ? ` (${c.deadline})` : ''}`; }
// Нэгдсэн бэлтгэл модал — (1) стандарт чеклист + (2) захиалгын бараа. Нэг газраас хүн оноож үүсгэнэ.
function openNomaadPrepChecklist(quoteNo) {
  const o = (state.nomaadOrders || []).find(x => x.quote_no === quoteNo);
  if (!o) return;
  const modal = document.getElementById('nomaad-assign-modal');
  document.getElementById('na-title').textContent = `Бэлтгэл · ${o.quote_no}`;
  document.getElementById('na-sub').textContent = `${o.company || ''} · ${o.camp || ''} ${o.tier || ''} · ${o.guests || 0} хүн · ${nomaadDatePlain(o.date_start)}`;
  const itemsEl = document.getElementById('na-items');
  const secHdr = (txt) => `<div style="font-size:12px;font-weight:800;color:var(--text);background:var(--bg-soft,#eef2f7);padding:8px 10px;margin:14px -4px 6px;border-radius:6px;">${escapeHtml(txt)}</div>`;
  const grpHdr = (txt) => `<div style="font-size:11px;font-weight:700;color:var(--text-soft);text-transform:uppercase;margin:10px 0 4px;">${escapeHtml(txt)}</div>`;
  const pickBtn = (type, idx, owner, exTask) => {
    const style = owner ? 'color:var(--text);border-style:solid;font-weight:600;' : 'color:var(--muted);border-style:dashed;font-weight:400;';
    const exId = exTask ? exTask.id : '';
    return `<button type="button" class="na-pick" data-na-type="${type}" data-na-item="${idx}" data-na-owner="${owner ? escapeHtml(owner) : ''}" data-na-exists="${exTask ? '1' : ''}" data-na-task-id="${escapeHtml(exId)}" data-na-orig="${owner ? escapeHtml(owner) : ''}" style="flex-shrink:0;min-width:140px;text-align:left;padding:7px 10px;border:1px dashed var(--border-strong);border-radius:var(--r-md);font-size:12px;background:var(--panel);cursor:pointer;${style}">${owner ? escapeHtml(memberName(owner)) : '+ Хүн сонгох'}</button>`;
  };
  const row = (label, meta, btn) => `<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);"><span style="flex:1;font-size:13px;min-width:0;">${label}${meta}</span>${btn}</div>`;
  // 1) Стандарт чеклист (үүссэнийг таниж тэмдэглэнэ)
  const byGroup = {};
  NOMAAD_PREP_CHECKLIST.forEach((c, idx) => { (byGroup[c.group] = byGroup[c.group] || []).push({ c, idx }); });
  const findExisting = (c) => (state.tasks || []).find(t => t.title === prepTaskTitle(c)
    && (t.desc || '').includes(`NOMAAD ${o.quote_no} `) && t.status !== 'deleted');
  let html = secHdr('1. Үйл ажиллагааны чеклист');
  html += Object.keys(byGroup).map(g => grpHdr(g) + byGroup[g].map(({ c, idx }) => {
    const ex = findExisting(c);
    const meta = `<span style="color:var(--muted);font-size:11px;">${c.deadline ? '· ' + escapeHtml(c.deadline) : ''}${c.photo ? ' · ✓зураг' : ''}${ex ? ' · <b style="color:var(--ok)">✓ үүссэн</b>' : ''}</span>`;
    return row(escapeHtml(c.title) + ' ', meta, pickBtn('prep', idx, ex ? (ex.assignee || '') : '', ex));
  }).join('')).join('');
  // 2) Захиалгын бараа (түрээсийн эд хогшил)
  const items = o.items || [];
  if (items.length) {
    html += secHdr('2. Захиалгын бараа');
    const byCat = {};
    items.forEach((it, idx) => { (byCat[it.category || 'Бусад'] = byCat[it.category || 'Бусад'] || []).push({ it, idx }); });
    html += Object.keys(byCat).map(cat => grpHdr(cat) + byCat[cat].map(({ it, idx }) =>
      row(escapeHtml(it.name || '') + ' ', `<span style="color:var(--muted);font-size:11px;">${it.qty || ''} ${escapeHtml(it.unit || '')}</span>`, pickBtn('item', idx, '', false))
    ).join('')).join('');
  }
  itemsEl.innerHTML = html;
  function setOwnerBtn(btn, key) {
    btn.dataset.naOwner = key || '';
    if (key) { btn.textContent = memberName(key); btn.style.color = 'var(--text)'; btn.style.borderStyle = 'solid'; btn.style.fontWeight = '600'; }
    else { btn.textContent = '+ Хүн сонгох'; btn.style.color = 'var(--muted)'; btn.style.borderStyle = 'dashed'; btn.style.fontWeight = '400'; }
  }
  itemsEl.querySelectorAll('button.na-pick').forEach(btn => {
    btn.onclick = async () => {
      const picked = await openGroupSinglePicker(btn.dataset.naOwner || '', 'Хэн хариуцах вэ?');
      if (picked === null) return;
      setOwnerBtn(btn, picked);
    };
  });
  document.getElementById('na-bulk').onclick = async () => {
    const picked = await openGroupSinglePicker('', 'Бүгдийг хэнд оноох вэ?');
    if (picked === null) return;
    itemsEl.querySelectorAll('button.na-pick').forEach(b => setOwnerBtn(b, picked));
  };
  document.getElementById('na-cancel').onclick = () => modal.classList.remove('open');
  document.getElementById('na-send').onclick = () => sendNomaadPrepTasks(quoteNo);
  modal.classList.add('open');
}
async function sendNomaadPrepTasks(quoteNo) {
  const o = (state.nomaadOrders || []).find(x => x.quote_no === quoteNo);
  if (!o) return;
  const modal = document.getElementById('nomaad-assign-modal');
  const btns = [...modal.querySelectorAll('button.na-pick')];
  // 1a) Чеклистийн ШИНЭ ажил — үүсээгүйг үүсгэнэ (хүн заавал биш).
  const prepPicks = btns.filter(b => b.dataset.naType === 'prep' && b.dataset.naExists !== '1')
    .map(b => ({ idx: Number(b.dataset.naItem), owner: b.dataset.naOwner || '' }));
  // 1b) Үүссэн ажлыг ДАХИН ХУВИАРЛАХ — хариуцагч өөрчлөгдсөн бол шинэчилнэ.
  const prepReassign = btns.filter(b => b.dataset.naType === 'prep' && b.dataset.naExists === '1'
      && (b.dataset.naOwner || '') !== (b.dataset.naOrig || ''))
    .map(b => ({ id: b.dataset.naTaskId, owner: b.dataset.naOwner || '' }));
  // 2) Захиалгын бараа — зөвхөн хүн сонгосныг хүнээр бүлэглэж нэг ажил болгоно.
  const byAssignee = {};
  btns.filter(b => b.dataset.naType === 'item' && b.dataset.naOwner).forEach(b => {
    const it = (o.items || [])[Number(b.dataset.naItem)];
    if (it) (byAssignee[b.dataset.naOwner] = byAssignee[b.dataset.naOwner] || []).push(it.name);
  });
  const itemOwners = Object.keys(byAssignee);
  if (!prepPicks.length && !prepReassign.length && !itemOwners.length) { showToast('Өөрчлөлт алга.', 'warn', 3000); return; }
  if (!(await showConfirm(`"${o.company}" — ${prepPicks.length} шинэ ажил + ${prepReassign.length} дахин хувиарлах + ${itemOwners.length} барааны ажил. Үргэлжлүүлэх үү?`, { okText: 'Тийм' }))) return;
  modal.classList.remove('open');
  const due = o.date_start ? String(o.date_start).slice(0, 10) : '';
  let n = 0, assigned = 0;
  const created = []; // үүсгэсэн бүх ажил — доор зэрэгцээ (арын) бичнэ
  // Чеклист — зүйл бүрд нэг ажил
  for (const p of prepPicks) {
    const c = NOMAAD_PREP_CHECKLIST[p.idx];
    if (!c) continue;
    const ass = p.owner || '';
    const t = {
      id: uid(), title: prepTaskTitle(c),
      desc: `NOMAAD ${o.quote_no} · ${o.company || ''} · ${o.camp || ''} ${o.tier || ''} · ${o.guests || 0} хүн\nАрга хэмжээ: ${nomaadDatePlain(o.date_start)}${c.deadline ? '\nЭцсийн хугацаа: ' + c.deadline : ''}${c.detail ? '\n\n' + c.detail : ''}`,
      branch: 'camp', project: '', assignee: ass, due, priority: 'high', status: 'open',
      requires_photo: !!c.photo, createdBy: state.me, created: Date.now() + n, comments: [], activity: [],
    };
    state.tasks.unshift(t); created.push(t);
    if (p.owner) { pushBroadcast(ass, { type: 'task_assigned', task_id: t.id, title: 'Шинэ бэлтгэл ажил', body: t.title }); assigned++; }
    n++;
  }
  // Захиалгын бараа — хүн тус бүрд нэг ажил
  for (const ass of itemOwners) {
    const t = {
      id: uid(), title: `Захиалгын бараа бэлтгэх · ${o.quote_no}`,
      desc: nomaadTaskDesc(o, byAssignee[ass]),
      branch: 'camp', project: '', assignee: ass, due, priority: 'high', status: 'open',
      requires_photo: true, createdBy: state.me, created: Date.now() + n, comments: [], activity: [],
    };
    state.tasks.unshift(t); created.push(t);
    pushBroadcast(ass, { type: 'task_assigned', task_id: t.id, title: 'Шинэ ажил', body: t.title }); assigned++;
    n++;
  }
  // Үүссэн ажлыг дахин хувиарлах (хариуцагч өөрчлөх)
  let reassigned = 0;
  for (const r of prepReassign) {
    const t = state.tasks.find(x => x.id === r.id);
    if (!t) continue;
    t.assignee = r.owner;
    created.push(t);
    if (r.owner) { pushBroadcast(r.owner, { type: 'task_assigned', task_id: t.id, title: 'Ажил хувиарлагдлаа', body: t.title }); }
    reassigned++;
  }
  saveLocal(); // локалд нэг л удаа бичнэ (шууд бэлэн)
  render();
  showToast(`${n} шинэ ажил, ${reassigned} дахин хувиарлав. Сервэрт хадгалж байна…`, 'success', 3500);
  // ─── Сервэрт ЗЭРЭГЦЭЭ (арын) бичнэ ───
  // Бүгд шинэ, давхцахгүй ID-тай append тул сериал гинж шаардлагагүй. Browser өөрөө
  // ~6 concurrent-аар хязгаарладаг тул 30 ажил ~8 секундэд, UI гацуулахгүй бичигдэнэ.
  // Сериал гинжээр нэг нэгээр бичих нь (~45с) гацалт үүсгэдэг байсныг арилгав.
  if (state.config.apiUrl) {
    created.forEach(t => {
      postWrite(state.config.apiUrl, { action: 'upsert', task: taskToWire(t) })
        .then(ok => { if (!ok) enqueueWrite({ kind: 'task', action: 'upsert', payload: t, ts: Date.now() }); })
        .catch(() => enqueueWrite({ kind: 'task', action: 'upsert', payload: t, ts: Date.now() }));
    });
  }
}

/* ─── Гүйцэтгэл (Phase 1: объектив метрик) ─────────────────
   Сарын task өгөгдлөөс ажилтан бүрийн объектив гүйцэтгэл.
   On-time = дуусгасан огноо <= эцсийн хугацаа. Оноо = (хугацаандаа + 0.5×хоцорч дуусгасан) / нийт.
   Энэ нь нэгдсэн оноонд 55% жинтэй орно (Phase 3-д 360° + KPI нэмэгдэнэ). */
function taskCompletedDate(t) {
  const ms = typeof t.completed_at === 'number' ? t.completed_at
    : (t.completed_at ? new Date(t.completed_at).getTime()
      : (t.executed_at ? new Date(t.executed_at).getTime()
        : (t.updated ? new Date(t.updated).getTime() : 0)));
  return ms ? new Date(ms).toISOString().slice(0, 10) : '';
}
// Ажил хугацаанаасаа хэдэн хоног хоцорсон (+) эсвэл эрт (−) дууссан бэ. null = тооцох боломжгүй.
function taskLatenessDays(t) {
  if (!t || t.status !== 'done') return null;
  const cd = taskCompletedDate(t);
  const due = String(t.due || '').slice(0, 10);
  if (!cd || !due) return null;
  return Math.round((new Date(cd + 'T00:00:00') - new Date(due + 'T00:00:00')) / 86400000);
}
function taskLatenessLabel(t) {
  const d = taskLatenessDays(t);
  if (d == null) return '';
  if (d > 0) return `<span style="color:var(--danger);font-weight:700;">⚠ ${d} хоног хоцорсон</span>`;
  if (d === 0) return `<span style="color:var(--ok);font-weight:700;">✓ Хугацаандаа дуусгасан</span>`;
  return `<span style="color:var(--ok);font-weight:700;">✓ ${-d} хоногийн өмнө дуусгасан</span>`;
}
function objectiveMetrics(key, month) {
  const today = todayStr();
  const mine = (state.tasks || []).filter(t =>
    t.assignee === key && t.status !== 'deleted' && t.kind !== 'act_parent'
    // Зөвхөн удирдлагаас өгсөн ажил — өөртөө оноосон ажлаар оноо нэмэхээс сэргийлнэ.
    && t.createdBy && t.createdBy !== key
    && (t.due || '').slice(0, 7) === month);
  const total = mine.length;
  let done = 0, onTime = 0, late = 0, overdue = 0;
  mine.forEach(t => {
    if (t.status === 'done') {
      done++;
      const cd = taskCompletedDate(t);
      if (cd && t.due && cd <= t.due) onTime++; else late++;
    } else if (t.due && t.due < today) { overdue++; }
  });
  const score = total ? Math.round(100 * (onTime + 0.5 * late) / total) : null;
  // Цөөн ажилтай үед оноо найдваргүй (2 амар ажил → 100%). Тэмдэглэж, нэгдсэн онооноос хасна.
  const lowData = total > 0 && total < MIN_OBJ_TASKS;
  return { total, done, onTime, late, overdue, score, lowData };
}
const MIN_OBJ_TASKS = 3;
/* ─── Нэгдсэн оноо (Объектив 40% + Ажлын чанар 40% + 360° 20%) + бонус ─── */
const PERF_WEIGHTS = { objective: 0.40, quality: 0.40, eval360: 0.20 };
const EVAL_COMPETENCIES = [
  { id: 'responsibility', label: 'Хариуцлага' },
  { id: 'quality', label: 'Чанар' },
  { id: 'teamwork', label: 'Багийн ажиллагаа' },
  { id: 'initiative', label: 'Санаачлага' },
];

async function loadEvaluations() {
  const url = state.config.evalUrl;
  if (!url) return;
  try {
    const r = await fetchWithTimeout(withKey(url + '?t=' + Date.now()), { headers: { 'Accept': 'application/json' } }, 15000);
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const data = await r.json();
    state.evaluations = Array.isArray(data) ? data : (data.evaluations || []);
    try { localStorage.setItem('evaluations', JSON.stringify(state.evaluations)); } catch(e) {}
    if (typeof render === 'function') render();
  } catch(e) { console.warn('loadEvaluations fail', e); }
}

async function saveEvaluation(ratee, fields) {
  const period = state.perfMonth;
  const id = `${period}|${state.me}|${ratee}`;
  const row = { id, period, ratee, rater: state.me, ts: new Date().toISOString(), ...fields };
  const idx = state.evaluations.findIndex(e => e.id === id);
  if (idx >= 0) state.evaluations[idx] = { ...state.evaluations[idx], ...row }; else state.evaluations.push(row);
  render();
  const url = state.config.evalUrl;
  if (!url) return;
  try {
    const r = await fetchWithTimeout(withKey(url), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(row) }, 15000);
    if (!r.ok) throw new Error('HTTP ' + r.status);
    showToast('Үнэлгээ хадгалагдлаа', 'success', 1500);
  } catch(e) { showToast('Алдаа: ' + e.message, 'error'); }
}

/* ─── Гүйцэтгэлийн суутгал: нэмэх / устгах (evaluations-д type=penalty мөр) ─── */
async function postEvalRow(row) {
  const idx = state.evaluations.findIndex(e => e.id === row.id);
  if (idx >= 0) state.evaluations[idx] = { ...state.evaluations[idx], ...row }; else state.evaluations.push(row);
  render();
  const url = state.config.evalUrl;
  if (!url) { showToast('evaluations backend тохируулаагүй', 'warn'); return; }
  const r = await fetchWithTimeout(withKey(url), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(row) }, 15000);
  if (!r.ok) throw new Error('HTTP ' + r.status);
}
function openPenaltyModal(ratee, name) {
  const month = state.perfMonth;
  document.getElementById('penalty-modal')?.remove();
  const modal = document.createElement('div');
  modal.className = 'modal-bg'; modal.id = 'penalty-modal';
  const renderList = () => {
    const list = monthPenalties(ratee, month);
    return list.length ? list.map(p => `
      <div class="pen-item" data-pen-id="${escapeHtml(p.id)}">
        <span class="pen-pts">−${Number(p.kpi_pct) || 0}</span>
        <span class="pen-reason">${escapeHtml(p.note || 'шалтгаан тэмдэглээгүй')}</span>
        <button class="pen-del" title="Цуцлах">×</button>
      </div>`).join('') : '<div class="pen-empty">Энэ сард суутгал алга.</div>';
  };
  modal.innerHTML = `
    <div class="modal naq-modal" style="max-width:440px;">
      <h2>Суутгал · ${escapeHtml(name)}</h2>
      <p class="naq-sub">${month} сар · нэгдсэн гүйцэтгэлийн онооноос хасагдана</p>
      <div id="pen-list">${renderList()}</div>
      <div class="naq-grid" style="margin-top:14px;">
        <label>Хасах оноо<input id="pen-pts" type="number" min="1" max="100" inputmode="numeric" placeholder="жишээ: 10" /></label>
        <label class="full">Шалтгаан<input id="pen-reason" placeholder="Жишээ: 3 удаа хоцорсон" /></label>
      </div>
      <div class="naq-foot">
        <div class="naq-actions">
          <button class="btn" id="pen-cancel">Хаах</button>
          <button class="btn btn-primary" id="pen-add">➖ Суутгал нэмэх</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  modal.classList.add('open');
  const listEl = modal.querySelector('#pen-list');
  const refresh = () => { listEl.innerHTML = renderList(); wireDel(); };
  const wireDel = () => listEl.querySelectorAll('.pen-del').forEach(btn => btn.onclick = async (e) => {
    const id = e.target.closest('.pen-item').dataset.penId;
    const row = state.evaluations.find(x => x.id === id); if (!row) return;
    e.target.disabled = true;
    try { await postEvalRow({ ...row, kpi_pct: 0, ts: new Date().toISOString() }); refresh(); showToast('Суутгал цуцлагдлаа', 'success', 1500); }
    catch (err) { showToast('Алдаа: ' + err.message, 'error'); e.target.disabled = false; }
  });
  wireDel();
  modal.querySelector('#pen-cancel').onclick = () => modal.remove();
  modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
  modal.querySelector('#pen-add').onclick = async (e) => {
    const pts = Math.round(Number(modal.querySelector('#pen-pts').value) || 0);
    const reason = modal.querySelector('#pen-reason').value.trim();
    if (pts <= 0) { showToast('Хасах оноо (1+) оруулна уу', 'warn'); return; }
    if (!reason) { showToast('Шалтгаан заавал', 'warn'); return; }
    e.target.disabled = true;
    const ts = new Date().toISOString();
    const row = { id: `pen|${month}|${ratee}|${ts}`, period: month, ratee, rater: state.me, type: 'penalty', kpi_pct: pts, note: reason, ts };
    try {
      await postEvalRow(row);
      modal.querySelector('#pen-pts').value = ''; modal.querySelector('#pen-reason').value = '';
      refresh(); showToast(`−${pts} оноо суутгалаа`, 'success', 1800);
    } catch (err) { showToast('Алдаа: ' + err.message, 'error'); }
    e.target.disabled = false;
  };
}

function evalRowScore(e) {
  const vals = EVAL_COMPETENCIES.map(c => Number(e[c.id]) || 0).filter(v => v > 0);
  return vals.length ? Math.round((vals.reduce((a, b) => a + b, 0) / vals.length) * 20) : null;
}
function eval360Score(key, period) {
  const rows = (state.evaluations || []).filter(e => e.ratee === key && e.period === period);
  const mgr = rows.filter(e => e.type === 'manager').map(evalRowScore).filter(v => v != null);
  let peers = rows.filter(e => e.type === 'peer').map(evalRowScore).filter(v => v != null);
  const peerN = peers.length;
  if (peers.length >= 3) peers = peers.slice().sort((a, b) => a - b).slice(1, -1);  // outlier trim
  const mgrAvg = mgr.length ? mgr.reduce((a, b) => a + b, 0) / mgr.length : null;
  const peerAvg = peers.length ? peers.reduce((a, b) => a + b, 0) / peers.length : null;
  let num = 0, den = 0;
  if (mgrAvg != null) { num += mgrAvg * 2; den += 2; }
  if (peerAvg != null) { num += peerAvg; den += 1; }
  return { score: den ? Math.round(num / den) : null, raterCount: mgr.length + peerN };
}
/* ─── Ажлын чанар (даалгавар өгөгчийн ★ үнэлгээ) ───
   Даалгавар өгөгч (удирдлага) дуусгасан ажил бүрийг 1-5★ үнэлнэ. Үнэлгээ нь
   task.kpi_code баганд хадгалагдана (Sheet "KPI код" — backend засваргүй persist).
   Сарын дундаж ×20 → 0-100. Объектив (цагтаа)-оос ӨӨР хэмжүүр: чанар. */
// kpi_code = "<оноо>" эсвэл "<оноо>⟦N⟧<тайлбар>" — үнэлгээний тайлбарыг backend багана нэмэхгүйгээр хадгална.
const _QNOTE_SEP = '⟦N⟧';
function taskQualityRating(t) { return Number(String((t && t.kpi_code) || '').split(_QNOTE_SEP)[0]) || 0; }
function taskQualityNote(t) { const p = String((t && t.kpi_code) || '').split(_QNOTE_SEP); return p.length > 1 ? p.slice(1).join(_QNOTE_SEP).trim() : ''; }
function encodeQuality(rating, note) { note = String(note || '').trim(); return note ? (rating + _QNOTE_SEP + note) : String(rating); }
function taskQualityScore(key, month) {
  const done = (state.tasks || []).filter(t =>
    t.assignee === key && t.status === 'done' && t.kind !== 'act_parent'
    && t.createdBy && t.createdBy !== key
    && (t.due || '').slice(0, 7) === month);
  const rated = done.map(t => taskQualityRating(t)).filter(v => v >= 1 && v <= 5);
  if (!rated.length) return { score: null, rated: 0, doneTotal: done.length };
  const avg = rated.reduce((a, b) => a + b, 0) / rated.length;
  return { score: Math.round(avg * 20), rated: rated.length, doneTotal: done.length, avg: Math.round(avg * 10) / 10 };
}
// Ажил дууссан ч ҮҮСГЭГЧ (даалгавар өгөгч) чанарын үнэлгээ өгөөгүй бол "хаагдаагүй" — үнэлгээ хүлээж буй.
// taskQualityScore-той нийцтэй: act_parent/санхүүгээс бусад, createdBy≠гүйцэтгэгч, оноогүй ажил.
function needsRating(t) {
  if (!t || t.status !== 'done') return false;
  if (t.kind === 'finance_request' || t.kind === 'act_parent' || t._isFinance) return false;
  if (!t.createdBy || t.createdBy === t.assignee) return false;
  const q = taskQualityRating(t);
  return !(q >= 1 && q <= 5);
}
async function saveTaskQuality(id, rating, note) {
  const t = state.tasks.find(x => x.id === id);
  if (!t) return;
  t.kpi_code = encodeQuality(rating, note);
  try {
    await saveTask(t);
    showToast(`Ажлын чанар: ${rating}★ хадгалагдлаа`, 'success', 1800);
    closeTaskModal();
    render();
  }
  catch (e) { showToast('Алдаа: ' + e.message, 'error'); }
}
/* ─── Гүйцэтгэлийн суутгал (гар торгууль) ───
   Менежер тухайн ажилтанд тухайн сард шалтгаантай оноо хасч болно. evaluations
   хадгалалтыг дахин ашиглана: type='penalty', kpi_pct=хасах оноо, note=шалтгаан.
   id='pen|сар|ажилтан|ts' тул нэг сард олон суутгал болно. kpi_pct=0 → цуцлагдсан. */
function monthPenalties(key, period) {
  return (state.evaluations || []).filter(e =>
    e.type === 'penalty' && e.ratee === key && e.period === period && (Number(e.kpi_pct) || 0) > 0);
}
function penaltyTotal(key, period) {
  return monthPenalties(key, period).reduce((s, e) => s + (Number(e.kpi_pct) || 0), 0);
}
function unifiedScore(key, period) {
  const om = objectiveMetrics(key, period);
  const obj = om.score;
  const objLowData = om.lowData;
  const q = taskQualityScore(key, period);
  const quality = q.score;
  const e360 = eval360Score(key, period);
  const penalty = penaltyTotal(key, period);
  const parts = [];
  // Цөөн ажилтай объективийг (lowData) нэгдсэн онооноос хасна — хиймэл өндөр оноо/бонусаас сэргийлнэ.
  if (obj != null && !objLowData) parts.push([obj, PERF_WEIGHTS.objective]);
  if (quality != null) parts.push([quality, PERF_WEIGHTS.quality]);
  if (e360.score != null) parts.push([e360.score, PERF_WEIGHTS.eval360]);
  if (!parts.length) return { total: null, obj, objLowData, quality, qualityInfo: q, e360, partsUsed: 0, penalty, rawTotal: null };
  const wsum = parts.reduce((s, [, w]) => s + w, 0);
  const rawTotal = Math.round(parts.reduce((s, [v, w]) => s + v * w, 0) / wsum);
  // Суутгалыг нэгдсэн онооноос хасч 0-ээс доош болгохгүй.
  const total = Math.max(0, rawTotal - penalty);
  return { total, rawTotal, penalty, obj, objLowData, quality, qualityInfo: q, e360, partsUsed: parts.length };
}
function bonusPctForScore(s) {
  if (s == null) return 0;
  if (s >= 90) return 20; if (s >= 80) return 15; if (s >= 70) return 10; if (s >= 60) return 5; return 0;
}
const BONUS_MIN_PARTS = 2;
/* Бонус олгох эрх: дан нэг бүрэлдэхүүнээс (ихэвчлэн объектив) +20% олгох нь
   gaming/инфляци үүсгэдэг. Дор хаяж 2 бүрэлдэхүүн (объектив + KPI эсвэл 360°)
   байж байж бонус тооцно. Доош нь оноо харагдана, бонус 0. */
function eligibleBonus(u) {
  if (!u || u.total == null) return 0;
  if ((u.partsUsed || 0) < BONUS_MIN_PARTS) return 0;
  return bonusPctForScore(u.total);
}
const perfScoreColor = s => s == null ? 'var(--muted)' : s >= 85 ? 'var(--ok)' : s >= 60 ? 'var(--warn)' : 'var(--danger)';

function renderPerformance() {
  const isMgr = canManageOrders() || state.isCEO || canSeeWorkload();   // Багийн ачаалал эрхтэй удирдлага/захирал → баг харна
  const tab = (!isMgr && state.perfTab === 'all') ? 'me' : (state.perfTab || 'me');
  const cur = new Date().toISOString().slice(0, 7);
  const tabs = [{ id: 'me', label: 'Миний оноо' }, ...(isMgr ? [{ id: 'all', label: 'Бүх ажилтан' }] : []), { id: 'rate', label: 'Үнэлэх' }];
  const head = `<div class="perf-head">
    <div class="perf-month"><button class="btn perf-nav" data-perf-nav="-1">‹</button><span class="perf-month-label">${state.perfMonth}</span><button class="btn perf-nav" data-perf-nav="1"${state.perfMonth >= cur ? ' disabled' : ''}>›</button></div>
    <div class="perf-tabs">${tabs.map(t => `<button class="perf-tab${t.id === tab ? ' active' : ''}" data-perf-tab="${t.id}">${t.label}</button>`).join('')}</div>
  </div>`;
  const body = tab === 'all' ? renderPerfAll() : tab === 'rate' ? renderPerfRate() : renderPerfMe();
  return head + body;
}

function renderPerfMe() {
  const month = state.perfMonth;
  const u = unifiedScore(state.me, month);
  const me = findMember(state.me) || {};
  const bp = eligibleBonus(u);
  const base = Number(me.base_salary) || 0;
  const partial = u.total != null && (u.partsUsed || 0) < BONUS_MIN_PARTS;
  const bar = (label, val, w) => `<div class="perf-bar-row"><span>${label} <small>(${Math.round(w * 100)}%)</small></span><b>${val == null ? '—' : val}</b></div>`;
  const obj = objectiveMetrics(state.me, month);
  return `<div class="perf-me-card">
      <div class="perf-big-score" style="color:${perfScoreColor(u.total)}">${u.total == null ? '—' : u.total}<small>/100</small></div>
      <div class="perf-bonus">${bp ? `Урамшуулал: <b style="color:var(--ok)">+${bp}%</b>${base ? ` = ${fmtMoney(Math.round(base * bp / 100))}` : ''}` : partial ? `Урамшуулал: 0% <small>(хэсэгчилсэн дата — ${BONUS_MIN_PARTS}+ бүрэлдэхүүн хэрэгтэй)</small>` : 'Урамшуулал: 0% <small>(60+ оноо хэрэгтэй)</small>'}</div>
      <div class="perf-breakdown">
        ${bar('Объектив (цагтаа)', u.obj, PERF_WEIGHTS.objective)}
        ${bar('Ажлын чанар', u.quality, PERF_WEIGHTS.quality)}
        ${bar('360° үнэлгээ', u.e360.score, PERF_WEIGHTS.eval360)}
        ${u.penalty ? `<div class="perf-bar-row perf-penalty-row"><span>Суутгал ${u.rawTotal != null ? `<small>(${u.rawTotal} → ${u.total})</small>` : ''}</span><b>−${u.penalty}</b></div>` : ''}
      </div>
      ${u.penalty ? `<div class="perf-penalty-list">${monthPenalties(state.me, month).map(p => `<div class="perf-penalty-item"><span>−${Number(p.kpi_pct) || 0}</span> ${escapeHtml(p.note || 'шалтгаан тэмдэглээгүй')}</div>`).join('')}</div>` : ''}
      ${u.total != null && u.partsUsed < 3 ? `<div class="perf-partial" style="color:var(--warn);font-size:12px;margin:4px 0;">⚠ Хэсэгчилсэн дата — оноо ${u.partsUsed}/3 бүрэлдэхүүнээс гарсан</div>` : ''}
      <div class="perf-note">Ажил: ${obj.total} · хугацаандаа ${obj.onTime} · хоцорсон ${obj.overdue}.${obj.lowData ? ` <b style="color:var(--warn)">⚠ Хангалтгүй дата (${MIN_OBJ_TASKS}+ ажил хэрэгтэй — объектив оноо нэгдсэн онооноос хасагдсан).</b>` : ''} Чанар: ${u.qualityInfo && u.qualityInfo.rated ? `${u.qualityInfo.avg}★ (${u.qualityInfo.rated}/${u.qualityInfo.doneTotal} ажил үнэлэгдсэн)` : 'үнэлгээ хийгдээгүй'}. 360°: ${u.e360.raterCount} үнэлэгч.</div>
    </div>`;
}

function renderPerfAll() {
  const month = state.perfMonth;
  const active = (TEAM || []).filter(m => (m.status || 'идэвхтэй') === 'идэвхтэй' && isPermanentStaff(m) && memberInLens(m));
  const rows = active.map(m => ({ m, key: personKey(m), u: unifiedScore(personKey(m), month), base: Number(m.base_salary) || 0 }))
    .sort((a, b) => (b.u.total ?? -1) - (a.u.total ?? -1));
  const list = rows.map((r, i) => {
    const bp = eligibleBonus(r.u);
    return `<div class="perf-row">
      <div class="perf-rank">${i + 1}</div>
      <div class="perf-name"><b>${escapeHtml(r.m.name)}</b><div class="perf-sub">${escapeHtml(r.m.role || '')} · 360°: ${r.u.e360.raterCount} үнэлэгч${r.u.penalty ? ` · <span style="color:var(--danger)">−${r.u.penalty} суутгал</span>` : ''}</div><button class="perf-penalty-btn" data-penalty-key="${escapeHtml(r.key)}" data-penalty-name="${escapeHtml(r.m.name)}">➖ Суутгал</button></div>
      <div class="perf-metrics"><span title="${r.u.objLowData ? 'Объектив — хангалтгүй дата, онооноос хасагдсан' : 'Объектив (цагтаа)'}">об ${r.u.obj ?? '—'}${r.u.objLowData ? '⚠' : ''}</span><span title="Ажлын чанар${r.u.qualityInfo && r.u.qualityInfo.rated ? ` — ${r.u.qualityInfo.avg}★ (${r.u.qualityInfo.rated}/${r.u.qualityInfo.doneTotal})` : ' — үнэлгээгүй'}">чан ${r.u.quality ?? '—'}</span><span title="360°">360 ${r.u.e360.score ?? '—'}</span></div>
      <div class="perf-score" style="color:${perfScoreColor(r.u.total)}" title="${r.u.total != null && r.u.partsUsed < 3 ? `Хэсэгчилсэн дата — ${r.u.partsUsed}/3 бүрэлдэхүүн` : ''}">${r.u.total ?? '—'}${r.u.total != null && r.u.partsUsed < 3 ? '<sup style="color:var(--warn);font-size:11px;">⚠</sup>' : ''}</div>
      <div class="perf-bonus-cell">${bp ? `+${bp}%${r.base ? `<br><small>${fmtMoney(Math.round(r.base * bp / 100))}</small>` : ''}` : '—'}</div>
    </div>`;
  }).join('');
  return `<div class="perf-list"><div class="perf-row perf-row-head"><div class="perf-rank">#</div><div class="perf-name">Ажилтан</div><div class="perf-metrics">Задаргаа</div><div class="perf-score">Оноо</div><div class="perf-bonus-cell">Бонус</div></div>${list}</div>
    <div class="perf-note" style="margin-top:10px;">Бонус = үндсэн цалин × хувь. CEO баталгаажуулна. <b>Бонус авахад дор хаяж ${BONUS_MIN_PARTS} бүрэлдэхүүн (объектив + ажлын чанар эсвэл 360°) хэрэгтэй</b> — дан объективаас бонус олгохгүй. Calibration: маш олон 5★ эсвэл харилцан өндөр оноог шалгаарай.</div>`;
}

function renderPerfRate() {
  const month = state.perfMonth;
  const me = findMember(state.me) || {};
  const myBranches = memberBranchesOf(me);
  const myLevel = Number(me.level) || 0;
  const active = (TEAM || []).filter(m => (m.status || 'идэвхтэй') === 'идэвхтэй' && isPermanentStaff(m));
  const targets = active.filter(m => {
    const k = personKey(m);
    if (!memberInLens(m)) return false;                 // толгойн лензээр (Бүх ажилтан таб-тай нийцүүлэв)
    if (k === state.me) return true;
    if (state.isCEO || myLevel >= 80) return true;      // CEO/менежер бүгдийг үнэлнэ (салбаргүй үнэлэгч гацахгүй)
    if (!myBranches.length) return false;
    return memberBranchesOf(m).some(b => myBranches.includes(b));
  });
  const cards = targets.map(m => {
    const key = personKey(m);
    const isSelf = key === state.me;
    const type = isSelf ? 'self' : (myLevel >= 60 && (Number(m.level) || 0) < myLevel ? 'manager' : 'peer');
    const ex = (state.evaluations || []).find(e => e.id === `${month}|${state.me}|${key}`);
    const typeLbl = type === 'manager' ? 'удирдсан' : type === 'self' ? 'өөрөө' : 'хамт';
    return `<div class="perf-rate-card" data-rate-key="${escapeHtml(key)}" data-rate-type="${type}">
      <div class="perf-rate-head"><div><b>${escapeHtml(m.name)}</b> <span class="perf-sub">${typeLbl}</span></div>${ex ? '<span class="perf-done">✓ үнэлсэн</span>' : ''}</div>
      <div class="perf-rate-body">
        ${EVAL_COMPETENCIES.map(c => `<div class="perf-comp"><span>${c.label}</span><div class="perf-stars" data-comp="${c.id}"${ex && Number(ex[c.id]) ? ` data-val="${Number(ex[c.id])}"` : ''}>${[1, 2, 3, 4, 5].map(n => `<span class="perf-star${ex && Number(ex[c.id]) >= n ? ' on' : ''}" data-star="${n}">★</span>`).join('')}</div></div>`).join('')}
        <textarea class="perf-rate-note" placeholder="Тэмдэглэл (1 эсвэл 5 өгвөл заавал)">${ex ? escapeHtml(ex.note || '') : ''}</textarea>
        <button class="btn btn-primary perf-rate-save">Хадгалах</button>
      </div>
    </div>`;
  }).join('');
  return `<div class="perf-note">${month} сард үнэлэх хүмүүс (таны салбар). 1-5★. Хамт олны оноо нэргүй нэгтгэгдэнэ.</div><div class="perf-rate-list">${cards}</div>`;
}

function attachPerformanceHandlers() {
  document.querySelectorAll('[data-perf-tab]').forEach(b => b.onclick = () => { state.perfTab = b.dataset.perfTab; render(); });
  document.querySelectorAll('[data-penalty-key]').forEach(b => b.onclick = () => {
    if (!(canManageOrders() || state.isCEO)) { showToast('Зөвхөн удирдлага суутгал хийнэ', 'warn'); return; }
    openPenaltyModal(b.dataset.penaltyKey, b.dataset.penaltyName);
  });
  document.querySelectorAll('[data-perf-nav]').forEach(btn => btn.addEventListener('click', () => {
    const [y, m] = state.perfMonth.split('-').map(Number);
    const d = new Date(y, m - 1 + Number(btn.dataset.perfNav), 1);
    const next = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    if (next > new Date().toISOString().slice(0, 7)) return;
    state.perfMonth = next; render();
  }));
  document.querySelectorAll('.perf-rate-card').forEach(card => {
    card.querySelectorAll('.perf-stars').forEach(stars => stars.querySelectorAll('.perf-star').forEach(star => {
      star.onclick = () => {
        const n = Number(star.dataset.star);
        stars.querySelectorAll('.perf-star').forEach(s => s.classList.toggle('on', Number(s.dataset.star) <= n));
        stars.dataset.val = n;
      };
    }));
    const saveBtn = card.querySelector('.perf-rate-save');
    if (saveBtn) saveBtn.onclick = (e) => {
      const key = card.dataset.rateKey, type = card.dataset.rateType;
      const fields = { type };
      let any = false, extreme = false;
      EVAL_COMPETENCIES.forEach(c => {
        const stars = card.querySelector(`.perf-stars[data-comp="${c.id}"]`);
        const v = Number(stars?.dataset.val || 0);
        fields[c.id] = v || ''; if (v) any = true; if (v === 1 || v === 5) extreme = true;
      });
      const note = card.querySelector('.perf-rate-note').value.trim();
      if (!any) { showToast('Дор хаяж нэг чадвар үнэлнэ үү', 'warn'); return; }
      if (extreme && !note) { showToast('1 эсвэл 5 өгвөл тэмдэглэл заавал', 'warn'); return; }
      fields.note = note;
      withBusy(e.currentTarget, () => saveEvaluation(key, fields), { successText: 'Хадгалсан' });
    };
  });
}

// ── app_config (VPS Postgres, PostgREST anon) key-value тохиргоо — сайттай хуваалцана ──
async function loadAppConfig(key) {
  if (!DB_ANON_KEY) return null;
  try {
    const r = await fetchWithTimeout(`${DB_URL}/rest/v1/app_config?key=eq.${encodeURIComponent(key)}&select=value`,
      { headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + DB_ANON_KEY } }, 15000);
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const rows = await r.json();
    return rows[0] ? rows[0].value : null;
  } catch (e) { console.warn('loadAppConfig fail', key, e.message); return null; }
}
async function saveAppConfig(key, value) {
  const r = await fetchWithTimeout(`${DB_URL}/rest/v1/app_config?on_conflict=key`, {
    method: 'POST',
    headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' },
    body: JSON.stringify({ key, value, updated_at: new Date().toISOString() }),
  }, 20000);
  if (!r.ok) throw new Error('HTTP ' + r.status);
}
// Сайтын (mevent.mn) ангиллын бүлэг + дэд ангилал оноолтыг засах модал.
let _cgSeq = 0;
async function openCategoryGroupsModal() {
  const groups0 = await loadAppConfig('mevent_category_groups');
  if (!Array.isArray(groups0)) { showToast('Бүлгийн тохиргоо олдсонгүй', 'error'); return; }
  // Дэд ангилал = барааны бодит category + тохиргоон дахь subs (нэгдэл)
  const leafSet = new Set((state.products || []).map(p => p.category).filter(Boolean));
  groups0.forEach(g => (g.subs || []).forEach(s => leafSet.add(s)));
  const leafCats = [...leafSet].sort((a, b) => String(a).localeCompare(String(b), 'mn'));
  // Дотоод засварын төлөв: групп бүрд тогтвортой id
  const groups = groups0.map(g => ({ id: 'g' + (++_cgSeq), name: g.name }));
  const assign = {};  // leafCat → groupId ('' = бүлэггүй)
  leafCats.forEach(c => { const g = groups0.find(x => Array.isArray(x.subs) && x.subs.includes(c)); assign[c] = g ? groups[groups0.indexOf(g)].id : ''; });

  document.getElementById('catgrp-modal')?.remove();
  const modal = document.createElement('div');
  modal.className = 'modal-bg'; modal.id = 'catgrp-modal';
  document.body.appendChild(modal);

  const syncFromDom = () => {
    modal.querySelectorAll('.cg-name').forEach(inp => { const g = groups.find(x => x.id === inp.dataset.id); if (g) g.name = inp.value; });
    modal.querySelectorAll('.cg-assign').forEach(sel => { assign[sel.dataset.cat] = sel.value; });
  };
  const optsFor = (cur) => `<option value="">— Бүлэггүй —</option>` + groups.map(g => `<option value="${g.id}"${cur === g.id ? ' selected' : ''}>${escapeHtml(g.name || '(нэргүй)')}</option>`).join('');
  const render = () => {
    modal.innerHTML = `<div class="modal" style="max-width:560px;">
      <h2>🗂 Ангиллын бүлгүүд</h2>
      <p style="font-size:12px;color:var(--muted);margin:0 0 12px;">Сайтын (mevent.mn) цэсний том бүлэг + дэд ангилал аль бүлэгт харагдахыг тохируулна.</p>
      <div style="font-size:11px;font-weight:700;color:var(--muted);margin:2px 0 6px;">ТОМ БҮЛГҮҮД</div>
      <div id="cg-groups">${groups.map(g => `
        <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;">
          <input class="cg-name" data-id="${g.id}" value="${escapeHtml(g.name)}" placeholder="Бүлгийн нэр" style="flex:1;min-width:0;padding:8px 10px;border:1px solid var(--border-strong);border-radius:8px;font-size:13.5px;font-weight:600;background:var(--panel);color:var(--text);">
          <button class="cg-del" data-id="${g.id}" title="Бүлэг устгах" style="flex:0 0 auto;width:34px;height:34px;border:1px solid var(--border-strong);border-radius:8px;background:var(--panel);color:var(--danger);font-size:18px;cursor:pointer;">×</button>
        </div>`).join('')}</div>
      <button class="btn" id="cg-add" style="width:100%;margin-bottom:14px;">+ Шинэ бүлэг</button>
      <div style="font-size:11px;font-weight:700;color:var(--muted);margin:2px 0 6px;">ДЭД АНГИЛАЛ → БҮЛЭГ</div>
      <div id="cg-cats" style="max-height:38vh;overflow-y:auto;">${leafCats.map(c => `
        <div style="display:flex;gap:8px;align-items:center;margin-bottom:5px;">
          <span style="flex:1;min-width:0;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(c)}</span>
          <select class="cg-assign" data-cat="${escapeHtml(c)}" style="flex:0 0 200px;padding:6px 8px;border:1px solid var(--border-strong);border-radius:8px;font-size:12.5px;background:var(--panel);color:var(--text);">${optsFor(assign[c])}</select>
        </div>`).join('')}</div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
        <button class="btn" id="cg-cancel">Болих</button>
        <button class="btn btn-primary" id="cg-save">💾 Хадгалах</button>
      </div>
    </div>`;
    // нэр өөрчлөх → сонголтын шошгыг шууд шинэчилнэ (id тогтвортой тул оноолт эвдрэхгүй)
    modal.querySelectorAll('.cg-name').forEach(inp => inp.oninput = () => {
      const g = groups.find(x => x.id === inp.dataset.id); if (g) g.name = inp.value;
      modal.querySelectorAll(`.cg-assign option[value="${inp.dataset.id}"]`).forEach(o => o.textContent = inp.value || '(нэргүй)');
    });
    modal.querySelectorAll('.cg-assign').forEach(sel => sel.onchange = () => { assign[sel.dataset.cat] = sel.value; });
    modal.querySelectorAll('.cg-del').forEach(btn => btn.onclick = () => {
      syncFromDom();
      const id = btn.dataset.id;
      const idx = groups.findIndex(g => g.id === id); if (idx >= 0) groups.splice(idx, 1);
      Object.keys(assign).forEach(c => { if (assign[c] === id) assign[c] = ''; });
      render();
    });
    modal.querySelector('#cg-add').onclick = () => { syncFromDom(); groups.push({ id: 'g' + (++_cgSeq), name: 'Шинэ бүлэг' }); render(); };
    modal.querySelector('#cg-cancel').onclick = () => modal.remove();
    modal.querySelector('#cg-save').onclick = async (e) => {
      syncFromDom();
      if (groups.some(g => !g.name.trim())) { showToast('Бүлгийн нэр хоосон байж болохгүй', 'warn'); return; }
      const newGroups = groups.map(g => ({ name: g.name.trim(), subs: leafCats.filter(c => assign[c] === g.id) }));
      e.target.disabled = true;
      try {
        await saveAppConfig('mevent_category_groups', newGroups);
        showToast('Ангиллын бүлэг шинэчлэгдлээ — сайтад тусна', 'success', 2500);
        modal.remove();
      } catch (err) { showToast('Алдаа: ' + err.message, 'error'); e.target.disabled = false; }
    };
  };
  render();
  modal.classList.add('open');
  modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
}

// Сайтын ангиллын бүлгүүд (default) — сайттай ижил бүтэц. app_config-оос override.
const _CAT_GROUPS_FALLBACK = [
  { name: 'Тайз, хөгжим, гэрэлтүүлэг', subs: ['Тайз', 'Хөгжим', 'Гэрэлтүүлэг', 'Эффект'] },
  { name: 'Ширээ, тавилга', subs: ['Ширээ, сандал, бүтээлэг', 'Засал, тохижилт'] },
  { name: 'Асар, майхан', subs: ['Асар', 'Майхан', 'Татдаг асар'] },
  { name: 'Хоол, гал тогоо', subs: ['Ресторан хэрэгсэл', 'Гал тогоо'] },
  { name: 'Техник, тоног төхөөрөмж', subs: ['Эрчим хүч, цахилгаан', 'Багаж, тоног төхөөрөмж', 'Халаалт, агааржуулалт', 'Цэвэрлэгээ', 'Тээврийн хэрэгсэл'] },
];
// Ангиллын filter dropdown-ыг сайтын бүлгээр (optgroup) — group→дэд ангилал, бусад нь тусад нь.
function _prodCatOptsGrouped(cats, sel) {
  const groups = Array.isArray(state.catGroups) && state.catGroups.length ? state.catGroups : _CAT_GROUPS_FALLBACK;
  const opt = (c) => `<option value="${escapeHtml(c)}"${c === sel ? ' selected' : ''}>${escapeHtml(c)}</option>`;
  const inGroup = new Set();
  let html = '<option value="all">📂 Бүх ангилал</option>';
  groups.forEach(g => {
    const subs = (g.subs || []).filter(s => cats.includes(s));
    if (!subs.length) return;
    subs.forEach(s => inGroup.add(s));
    html += `<optgroup label="${escapeHtml(g.name)}">${subs.map(opt).join('')}</optgroup>`;
  });
  const rest = cats.filter(c => !inGroup.has(c));
  if (rest.length) html += `<optgroup label="Бусад">${rest.map(opt).join('')}</optgroup>`;
  return html;
}
function renderProducts() {
  const all = state.products || [];
  // Сайтын ангиллын бүлгүүдийг нэг удаа lazy татна (dropdown-ыг сайтын бүлгээр харуулах)
  if (state.catGroups === undefined) { state.catGroups = null; loadAppConfig('mevent_category_groups').then(v => { if (Array.isArray(v) && v.length) { state.catGroups = v; render(); } }); }
  state.prodFilter = state.prodFilter || 'all';
  state.prodBranch = state.prodBranch || 'all';
  // Ажилтан өөрийн салбарт ТҮГЖИГДЭНЭ (удирдлага/CEO/олон салбар бүгдийг харна)
  const _me = findMember(state.me) || {};
  const _myBr = memberBranchesOf(_me);   // override-aware (Sheet биш) — бусад view-тэй нэг эх сурвалж
  const _prodMgmt = state.isCEO || (Number(_me.level) || 0) >= 80 || _myBr.includes('shared') || _myBr.length !== 1;
  // Агуулах толгойн салбар ЛЕНЗИЙГ ДАГАНА. Ленз идэвхтэй (≠Бүгд) бол prodBranch = лензийн салбар
  // (нэг салбарт түгжигдсэн ажилтан ч лензээрээ автоматаар түгжигдэнэ — тусдаа map хэрэггүй).
  // Бүгд лензэд Агуулахын өөрийн доод таб (all/mevent/nomaad/catering/chimun) хүчинтэй.
  // Агуулах ГАНЦ толгойн лензээр — доод таб байхгүй. Бугд лензэд бүх салбар (мөр бүр 🎪2 ⛺3 задаргаатай).
  const _lensProd = lensToProd(effectiveBranchLens());   // null when 'all'
  state.prodBranch = _lensProd || 'all';
  let list = all.slice();
  if (state.prodBranch !== 'all') list = list.filter(p => branchQty(p, state.prodBranch) > 0);
  // Ангилал шүүлтүүр + эрэмбэлэлт (өртөг/үнэ/нөөц)
  state.prodCategory = state.prodCategory || 'all';
  state.prodSort = state.prodSort || 'name';
  if (state.prodCategory !== 'all') list = list.filter(p => p.category === state.prodCategory || (Array.isArray(p.all_categories) && p.all_categories.includes(state.prodCategory)));
  const costOf = (p) => (state.productCosts || {})[p.sku] || Number(p.cost) || 0;
  // Дутуу мэдээллийн шүүлт — зураггүй / өртөггүй / түрээсийн үнэгүй / хуваарилаагүй (нөхөх ажилд)
  state.prodMissing = state.prodMissing || 'all';
  if (state.prodMissing !== 'all') {
    const f = {
      nophoto: p => !String(p.photo || '').trim(),
      nocost: p => costOf(p) <= 0,
      noprice: p => (Number(p.price) || 0) <= 0,
      noalloc: p => (branchQty(p, 'chimun') + branchQty(p, 'mevent') + branchQty(p, 'nomaad') + branchQty(p, 'catering')) <= 0,
      nodate: p => !p.purchase_date,
    }[state.prodMissing];
    if (f) list = list.filter(f);
  }
  const _prodSorters = {
    name: (a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'mn'),
    value_desc: (a, b) => costOf(b) * (Number(b.stock) || 0) - costOf(a) * (Number(a.stock) || 0),
    cost_desc: (a, b) => costOf(b) - costOf(a),
    price_desc: (a, b) => (Number(b.price) || 0) - (Number(a.price) || 0),
    stock_desc: (a, b) => (Number(b.stock) || 0) - (Number(a.stock) || 0),
    purchase_asc: (a, b) => String(a.purchase_date || '9999-99-99').localeCompare(String(b.purchase_date || '9999-99-99')),
  };
  list = list.slice().sort(_prodSorters[state.prodSort] || _prodSorters.name);
  const rows = productListHtml(list);   // бараа бүр тусдаа мөр (хувилбар бүлэглэлт байхгүй)
  // Салбарын ленз — тухайн салбарт нөөцтэй барааг л харуулна (нэг барааг олон салбарт хувааж болно)
  const brQtySum = (k) => all.reduce((s, p) => s + branchQty(p, k), 0);
  const brCount = (k) => all.filter(p => branchQty(p, k) > 0).length;
  const _pb = state.prodBranch;   // = лензийн салбар эсвэл 'all'
  // (branchBar устсан — салбарын мэдээлэл prod-metabar дотор шингэсэн)
  // Улирал хаалт — NOMAAD салбар идэвхтэй (лензээр эсвэл табаар) + нөөцтэй + удирдах эрхтэй үед
  const _nomaadSum = brQtySum('nomaad');
  // Хувилбар цэвэрлэх тууз — хуучин дата дээр л гарна, цуцалмагц өөрөө алга болно
  const _vgLeft = all.filter(p => String(p.variant_group || '').trim() || String(p.variant_label || '').trim()).length;
  const variantClearBar = (_prodMgmt && _vgLeft > 0)
    ? `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:8px 0 2px;padding:9px 12px;background:rgba(124,58,237,.08);border:1px solid rgba(124,58,237,.28);border-radius:10px;">
        <span style="font-size:12.5px;color:var(--text);">🎨 ${_vgLeft} бараа хувилбар бүлэгт байна — сайтад нэг картад нэгтгэгдэж каталог цөөн харагдана.</span>
        <button class="btn btn-primary" id="prod-clear-variants" style="white-space:nowrap;">Хувилбар цуцлах (${_vgLeft})</button>
      </div>`
    : '';
  // Англи нэр — үнийн саналын EN хувилбарт хэрэглэнэ. Хоосон нь толиор автоматаар
  // бөглөгдөж болно (дараа нь гараар засаж болно). Багана байхгүй бол тууз гарахгүй.
  const _noEnN = state._prodHasNameEn === false ? 0 : all.filter(p => !String(p.name_en || '').trim()).length;
  const nameEnBar = (_prodMgmt && _noEnN > 0)
    ? `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:8px 0 2px;padding:9px 12px;background:rgba(37,99,235,.08);border:1px solid rgba(37,99,235,.28);border-radius:10px;">
        <span style="font-size:12.5px;color:var(--text);">🇬🇧 ${_noEnN} барааны англи нэр хоосон — англи үнийн саналд автомат орчуулга гарна.</span>
        <button class="btn btn-primary" id="prod-fill-nameen" style="white-space:nowrap;">Англи нэр бөглөх (${_noEnN})</button>
      </div>`
    : '';
  const seasonCloseBar = (_prodMgmt && state.prodBranch === 'nomaad' && _nomaadSum > 0)
    ? `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:8px 0 2px;padding:9px 12px;background:rgba(13,148,136,.08);border:1px solid rgba(13,148,136,.28);border-radius:10px;">
        <span style="font-size:12.5px;color:var(--text);">⛺ Улирал дууссан уу? NOMAAD-ийн бүх нөөцийг M-Event руу нэг товчоор буцаана.</span>
        <button class="btn btn-primary" id="prod-return-nomaad" style="white-space:nowrap;">⇄ Бүгдийг 🎪 M-Event руу (${_nomaadSum}ш)</button>
      </div>`
    : '';
  // Ангилал + эрэмбэ сонгогч
  const cats = [...new Set(all.flatMap(p => [p.category, ...(Array.isArray(p.all_categories) ? p.all_categories : [])]).filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b), 'mn'));
  const catOpts = _prodCatOptsGrouped(cats, state.prodCategory);   // сайтын бүлгээр (optgroup)
  const sortOpts = [['name', 'Нэр (А-Я)'], ['value_desc', '💰 Хөрөнгийн үнэ цэнэ ↓'], ['cost_desc', 'Нэгж өртөг ↓'], ['price_desc', 'Түрээсийн үнэ ↓'], ['stock_desc', 'Нөөц ↓'], ['purchase_asc', '📅 Хамгийн удаан эзэмшсэн']].map(([k, l]) => `<option value="${k}"${state.prodSort === k ? ' selected' : ''}>${l}</option>`).join('');
  const missCount = (key) => all.filter({ nophoto: p => !String(p.photo || '').trim(), nocost: p => costOf(p) <= 0, noprice: p => (Number(p.price) || 0) <= 0, noalloc: p => (branchQty(p, 'chimun') + branchQty(p, 'mevent') + branchQty(p, 'nomaad') + branchQty(p, 'catering')) <= 0, nodate: p => !p.purchase_date, noen: p => !String(p.name_en || '').trim() }[key]).length;
  const missOpts = [['all', '✅ Бүх мэдээлэл'], ['nophoto', '🖼 Зураггүй'], ['nocost', '💰 Өртөггүй'], ['noprice', '🏷 Түрээсийн үнэгүй'], ['noalloc', '📍 Хуваарилаагүй'], ['nodate', '📅 Огноогүй'], ['noen', '🇬🇧 Англи нэргүй']].map(([k, l]) => `<option value="${k}"${state.prodMissing === k ? ' selected' : ''}>${l}${k !== 'all' ? ` (${missCount(k)})` : ''}</option>`).join('');
  // ── ШҮҮЛТҮҮР — эвхэгддэг самбарт. Урьд нь 3 сонгогч ҮРГЭЛЖ нэг мөрөнд зэрэгцэж,
  // 390px дэлгэцэд шошго нь дунднаас тасарч («Гэрэлтүүлэ⌷», «Бүх мэ⌷») юугаар шүүж
  // байгаагаа ойлгох боломжгүй байв. Одоо нээхэд БҮТЭН нэртэй, доошоо давхарлана. ──
  const _fActive = (state.prodCategory !== 'all' ? 1 : 0) + (state.prodMissing !== 'all' ? 1 : 0) + (state.prodSort !== 'name' ? 1 : 0);
  const _fOpen = !!state.prodFiltersOpen;
  const filterBar = `<details class="prod-filters"${_fOpen ? ' open' : ''} id="prod-filters">
    <summary class="prod-filters-sum">Шүүлтүүр${_fActive ? `<span class="prod-filters-n">${_fActive}</span>` : ''}</summary>
    <div class="prod-filters-body">
      <label>Ангилал<select id="prod-cat">${catOpts}</select></label>
      <label>Мэдээллийн бүрдэл<select id="prod-missing">${missOpts}</select></label>
      <label>Эрэмбэ<select id="prod-sort">${sortOpts}</select></label>
      ${_prodMgmt ? '<button class="btn" id="prod-groups">Сайтын ангиллын бүлгүүд</button>' : ''}
      ${_fActive ? '<button class="btn prod-filters-clear" id="prod-filters-clear">Шүүлтүүр цэвэрлэх</button>' : ''}
    </div>
  </details>`;
  const costs = state.productCosts || {};
  // Хөрөнгийн үнэ цэнэ — салбар сонгосон бол тухайн салбарын тоогоор (qty_<салбар>), эс бөгөөс нийт нөөцөөр.
  const _valBranch = (state.prodBranch && state.prodBranch !== 'all') ? state.prodBranch : null;
  const _qtyVal = (p) => _valBranch ? branchQty(p, _valBranch) : (Number(p.stock) || 0);
  const assetValue = all.reduce((s, p) => s + (costs[p.sku] || 0) * _qtyVal(p), 0);
  const _inScope = all.filter(p => _qtyVal(p) > 0);
  const costedN = _inScope.filter(p => (costs[p.sku] || 0) > 0).length;
  const _valLabel = _valBranch ? `${branchInfo(_valBranch).icon} ${branchInfo(_valBranch).label} салбарын хөрөнгө` : 'Нийт хөрөнгийн үнэ цэнэ';
  // Хөрөнгийн үнэ цэнэ — өдөр бүр хэрэггүй тул тусдаа тууз эзлэхээ болиод мета мөрөнд шингэнэ
  const assetChip = (assetValue > 0 && _prodMgmt)
    ? `<span class="prod-meta-i" title="${escapeHtml(_valLabel)} · ${costedN}/${_inScope.length} барааны өртөг оруулсан">Хөрөнгө <b>${fmtMoneyShort(assetValue)}</b> <span class="prod-meta-dim">(${costedN}/${_inScope.length})</span></span>`
    : '';
  // ── 2 ТУУЗ (урьд нь 6) ──
  // 1: хайлт · скан · шинэ бараа   2: шүүлтүүр · тоо · хөрөнгө · салбар
  // Эхний бараа хүртэлх зай утасны дэлгэцийн ~50%-иас ~20% болно.
  return `
    <div class="prod-toolbar">
      <input type="search" id="prod-search" class="prod-search" placeholder="Хайх (нэр, ангилал, SKU)..." value="${escapeHtml(state.productSearch || '')}">
      <button class="btn" id="prod-scan" title="QR скан">📷 Скан</button>
      <button class="btn btn-primary" id="prod-new">+ Шинэ</button>
    </div>
    <div class="prod-metabar">
      ${filterBar}
      <span class="prod-meta-i" id="prod-count"><b>${list.length}</b> бараа</span>
      ${assetChip}
      <span class="prod-meta-i prod-meta-dim">${_pb === 'all' ? 'Бүх салбар' : `${escapeHtml(branchInfo(_pb).label)} · ${brQtySum(_pb)}ш`}</span>
    </div>
    ${nameEnBar}
    ${variantClearBar}
    ${seasonCloseBar}
    <div class="prod-list">${rows ||'<div class="orders-empty"><div class="icon">📦</div>Энд бараа алга. "Шинэ" дарж нэмнэ үү.</div>'}</div>
  `;
}

// Барааны дэлгэрэнгүй/засах модал — шинэ (p=null) эсвэл засах (p=бараа). Бүх талбар нэг дор.
function openProductModal(p) {
  if (!can('products.edit')) { showToast('Танд бараа засах эрх олгогдоогүй', 'warn', 3000); return; }
  const isEdit = !!p;
  const cost = isEdit ? ((state.productCosts || {})[p.sku] || 0) : 0;
  const u = isEdit ? productUtilization(p.name) : { orders: 0, revenue: 0 };
  const invested = cost * (Number(p && p.stock) || 0);
  const roi = invested > 0 ? Math.round(u.revenue / invested * 100) : null;
  // Салбарын нөөцийн анхны утга — шинэ/түрээсийн бол бүгд M-Event, asset бол Чимун
  const _st0 = isEdit ? (Number(p.stock) || 0) : 1;
  let _qm0, _qc0, _qn0, _qk0;
  if (isEdit && (p.qty_mevent != null || p.qty_chimun != null || p.qty_nomaad != null || p.qty_catering != null)) {
    _qm0 = Number(p.qty_mevent) || 0; _qc0 = Number(p.qty_chimun) || 0; _qn0 = Number(p.qty_nomaad) || 0; _qk0 = Number(p.qty_catering) || 0;
  } else if (isEdit && String(p.type || 'rental') === 'asset') {
    _qc0 = _st0; _qm0 = 0; _qn0 = 0; _qk0 = 0;
  } else if (isEdit) {
    _qm0 = _st0; _qc0 = 0; _qn0 = 0; _qk0 = 0;
  } else {
    _qm0 = 0; _qc0 = 0; _qn0 = 0; _qk0 = 0;   // шинэ бараа — салбараа ИЛЭЭР сонгоно (чимээгүй default байхгүй)
  }
  const cats = [...new Set((state.products || []).map(x => x.category).filter(Boolean))].sort();
  const catOpts = cats.map(c => `<option value="${escapeHtml(c)}">`).join('');
  const v = (x) => escapeHtml((p && p[x]) || '');
  document.getElementById('prod-modal')?.remove();
  const modal = document.createElement('div');
  modal.className = 'modal-bg';
  modal.id = 'prod-modal';
  modal.innerHTML = `
    <div class="modal" style="max-width:540px;">
      <h2>${isEdit ? 'Бараа засах' : 'Шинэ бараа'}</h2>
      ${isEdit && (u.orders || cost) ? `<div class="pm-stats">📊 ${u.orders} удаа түрээслэгдсэн · Орлого <b>${fmtMoney(u.revenue)}</b>${cost ? ` · Нийт өртөг <b>${fmtMoney(invested)}</b>${roi != null ? ` · <b style="color:${roi >= 100 ? 'var(--ok)' : 'var(--warn)'}">${roi}% нөхсөн</b>` : ''}` : ''}</div>` : ''}
      <div class="pm-grid">
        <label class="pm-wide">Нэр *<input id="pm-name" value="${v('name')}" placeholder="Барааны нэр"></label>
        <label class="pm-wide">Англи нэр <span style="color:var(--muted);font-weight:400;">(үнийн саналын EN хувилбарт)</span><input id="pm-nameen" value="${v('name_en')}" placeholder="${escapeHtml(p && p.name ? enText(p.name) : 'English name')}"></label>
        <label>Ангилал<input id="pm-cat" list="pm-cats" value="${v('category')}" placeholder="Ангилал"><datalist id="pm-cats">${catOpts}</datalist></label>
        <label>Код <span style="color:var(--muted);font-weight:400;">(${isEdit ? 'систем' : 'автомат'})</span><input id="pm-code" value="${isEdit ? v('code') : ''}" placeholder="хадгалахад авто (M-xxx)" readonly style="background:var(--panel-hover);color:var(--text-soft,#666);cursor:not-allowed;"></label>
        <input type="hidden" id="pm-sku" value="${isEdit ? v('sku') : ''}">
        <label>Түрээсийн үнэ (₮)<input id="pm-price" type="text" inputmode="numeric" class="money-input" value="${moneyFmtInput(Number(p && p.price) || 0)}"></label>
        <label>Барьцаа (₮)<input id="pm-deposit" type="text" inputmode="numeric" class="money-input" value="${moneyFmtInput(Number(p && p.deposit) || 0)}"></label>
        <label>Нийт нөөц (ширхэг)<input id="pm-stock" type="number" value="${isEdit ? (Number(p.stock) || 0) : 1}"></label>
        <label>Нэгж өртөг (₮) *<input id="pm-cost" type="text" inputmode="numeric" class="money-input" value="${moneyFmtInput(cost || 0)}"></label>
        <label>📅 Худалдан авсан огноо${p && p.purchase_date && productAge(p.purchase_date) ? ` <span style="color:var(--muted);font-weight:400;">(${productAge(p.purchase_date)} ашигласан)</span>` : ''}<input id="pm-purchase" type="date" value="${escapeHtml(String((p && p.purchase_date) || '').slice(0, 10))}"></label>
        <label>⚠ Эвдэрсэн<input id="pm-broken" type="number" min="0" value="${Number(p && p.broken) || 0}"></label>
        <label>🔧 Засварт<input id="pm-maintenance" type="number" min="0" value="${Number(p && p.maintenance) || 0}"></label>
        <label class="pm-wide">🔗 Гарал үүсэл (хаанаас авсан)${/^https?:\/\//.test((p && (p.source_url || p.supplier)) || '') ? ` <a href="${escapeHtml(p.source_url || p.supplier)}" target="_blank" rel="noopener" style="font-weight:400;">нээх ↗</a>` : ''}<input id="pm-source" value="${escapeHtml((p && (p.source_url || p.supplier)) || '')}" placeholder="ж: taobao/1688 линк, дэлгүүр, Монголоос г.м."></label>
        <label class="pm-wide">🎬 Бичлэг/зураг үзэх холбоос${/^https?:\/\//.test((p && p.media_url) || '') ? ` <a href="${escapeHtml(p.media_url)}" target="_blank" rel="noopener" style="font-weight:400;">нээх ↗</a>` : ''}<input id="pm-media" value="${escapeHtml((p && p.media_url) || '')}" placeholder="ж: YouTube линк, эсвэл доор видео файл оруулна">
          <div style="display:flex;gap:8px;align-items:center;margin-top:6px;flex-wrap:wrap;">
            <button type="button" id="pm-media-upload" style="display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;padding:7px 13px;border:1px solid var(--border-strong,#ccc);border-radius:8px;background:var(--panel,#fff);color:var(--text,#111);cursor:pointer;">📤 Видео файл оруулах</button>
            <input type="file" id="pm-media-file" accept="video/*" style="display:none;">
            <span id="pm-media-status" style="font-size:12px;color:var(--muted,#888);"></span>
          </div>
          <div style="font-size:11px;color:var(--muted,#888);margin-top:3px;">Өөрсдийн бичлэг оруулбал сайтад цэвэрхэн (YouTube-гүй) тоглоно. Богино клип (15-30 сек), 80MB-аас бага.</div>
        </label>
      </div>
      <div class="pm-working" id="pm-working"></div>
      <div class="pm-branch">
        <div class="pm-branch-head">🏢 Салбарын хуваарилалт${isEdit ? '' : ' *'} <span>— аль салбарт хэдэн ширхэг. <b>M-Event-д 1+ бол сайтад түрээслэгдэнэ.</b></span></div>
        ${isEdit ? '' : `<div class="pm-branch-pick" id="pm-branch-pick" style="display:flex;gap:8px;flex-wrap:wrap;margin:8px 0;">
          <button type="button" class="f-link-type" data-brpick="m">🎪 M-Event</button>
          <button type="button" class="f-link-type" data-brpick="c">🏢 Чимун дотоод</button>
          <button type="button" class="f-link-type" data-brpick="n">⛺ NOMAAD</button>
        </div>`}
        <div class="pm-branch-grid">
          <label>🎪 M-Event<input type="number" min="0" id="pm-qm" value="${_qm0}"></label>
          <label>🏢 Чимун дотоод<input type="number" min="0" id="pm-qc" value="${_qc0}"></label>
          <label>⛺ NOMAAD<input type="number" min="0" id="pm-qn" value="${_qn0}"></label>
          <label>🍽 Катеринг<input type="number" min="0" id="pm-qk" value="${_qk0}"></label>
        </div>
        <div class="pm-branch-status" id="pm-branch-status"></div>
      </div>
      <label class="pm-rentable">
        <input type="checkbox" id="pm-ispackage" ${isPackage(p) ? 'checked' : ''}>
        <span><b>📦 Багц бараа</b> — хэд хэдэн барааг нэг үнээр (ж: "Дуу багц"). Нөөц нь бүрэлдэхүүнээс автоматаар тооцогдоно.</span>
      </label>
      <div id="pm-bundle" class="pm-bundle"${isPackage(p) ? '' : ' hidden'}>
        <div id="pm-bundle-list"></div>
        <button type="button" class="btn pm-bundle-add" id="pm-bundle-add">+ Бараа нэмэх</button>
        <datalist id="pm-prod-list">${(state.products || []).filter(x => !isPackage(x) && x.name).map(x => `<option value="${escapeHtml(x.name)}">`).join('')}</datalist>
        <div id="pm-bundle-sum" class="pm-bundle-sum"></div>
      </div>
      <label class="pm-rentable">
        <input type="checkbox" id="pm-isservice" ${isService(p) ? 'checked' : ''}>
        <span><b>🛠 Үйлчилгээ</b> — суурилуулалт, оператор г.м. (хүргэлт бол захиалгын хэсэгт тусад нь). Нөөц/агуулах/ROI-д ОРОХГҮЙ, зөвхөн үнэтэй мөр.</span>
      </label>
      <div class="pm-block">Зураг <span style="color:var(--muted);font-weight:400;">(эхнийх = нүүр зураг, сайтад gallery)</span>
        <div id="pm-gallery" class="pm-gallery"></div>
        <div class="pm-gallery-actions">
          <label class="btn pnf-upbtn" for="pm-photo-file">📷 Зураг нэмэх</label>
          <input type="file" id="pm-photo-file" accept="image/*" multiple hidden>
        </div>
      </div>
      <label class="pm-block">Тайлбар <span style="color:var(--muted);font-weight:400;">(сайтад харагдана)</span>
        <textarea id="pm-desc" rows="3" placeholder="Барааны тайлбар...">${v('description')}</textarea>
      </label>
      ${isEdit && p.sku ? `<div class="pm-block">QR шошго <span style="color:var(--muted);font-weight:400;">(хэвлэж бараандаа наа → камераар сканнердана)</span><div id="pm-qr" class="pm-qr">QR…</div></div>` : ''}
      <div class="modal-actions" style="margin-top:16px;">
        <button class="btn" id="pm-cancel">Болих</button>
        <button class="btn btn-primary" id="pm-save">${isEdit ? '💾 Хадгалах' : 'Нэмэх'}</button>
      </div>
    </div>`;
  document.body.appendChild(modal);
  if (isEdit && p.sku) renderProductQR(modal.querySelector('#pm-qr'), p.sku);
  // Олон зургийн менежер — эхний зураг = нүүр. modal._images-д хадгална (submitProductModal уншина).
  let images = (p && Array.isArray(p.photos) && p.photos.length) ? p.photos.slice() : (p && p.photo ? [p.photo] : []);
  modal._images = images;
  const gallery = modal.querySelector('#pm-gallery');
  function renderGallery() {
    gallery.innerHTML = images.length ? images.map((u, i) => `
      <div class="pm-thumb${i === 0 ? ' main' : ''}">
        <img src="${escapeHtml(u)}" alt="" loading="lazy">
        ${i === 0 ? '<span class="pm-thumb-tag">Нүүр</span>' : `<button type="button" class="pm-thumb-star" data-star="${i}" title="Нүүр болгох">★</button>`}
        <button type="button" class="pm-thumb-rm" data-rm="${i}" title="Хасах">×</button>
      </div>`).join('') : '<div class="pm-gallery-empty">Зураг алга — доороос нэмнэ үү</div>';
  }
  renderGallery();
  gallery.onclick = (e) => {
    const star = e.target.closest('[data-star]'), rm = e.target.closest('[data-rm]');
    if (star) { const i = +star.dataset.star; const [u] = images.splice(i, 1); images.unshift(u); renderGallery(); }
    else if (rm) { images.splice(+rm.dataset.rm, 1); renderGallery(); }
  };
  const fileInput = modal.querySelector('#pm-photo-file');
  fileInput.onchange = async () => {
    const files = [...(fileInput.files || [])]; if (!files.length) return;
    for (const f of files) {
      try { const url = await uploadProductImage(f); images.push(url); renderGallery(); }
      catch (e) { showToast('Зураг алдаа: ' + e.message, 'error', 4000); }
    }
    fileInput.value = '';
  };
  // Видео файл оруулах → VPS-д байршуулж #pm-media-д URL тавина (сайт native тоглуулагчаар харуулна)
  const vBtn = modal.querySelector('#pm-media-upload');
  const vFile = modal.querySelector('#pm-media-file');
  const vStatus = modal.querySelector('#pm-media-status');
  const vMedia = modal.querySelector('#pm-media');
  if (vBtn && vFile) {
    vBtn.onclick = () => vFile.click();
    vFile.onchange = async () => {
      const f = (vFile.files || [])[0]; if (!f) return;
      vBtn.disabled = true; if (vStatus) vStatus.textContent = 'Байршуулж байна… (' + Math.round(f.size / 1048576) + 'MB, түр хүлээнэ үү)';
      try {
        const url = await uploadProductVideo(f);
        if (vMedia) vMedia.value = url;
        if (vStatus) { vStatus.textContent = '✓ Орлоо'; vStatus.style.color = 'var(--success,#2f7d5b)'; }
      } catch (e) {
        if (vStatus) { vStatus.textContent = '✗ ' + e.message; vStatus.style.color = 'var(--danger,#c2453b)'; }
        showToast('Видео алдаа: ' + e.message, 'error', 5000);
      } finally { vBtn.disabled = false; vFile.value = ''; }
    };
  }
  // Багц бараа — бүрэлдэхүүний жагсаалт ({sku,qty}). modal._bundle-д хадгална.
  let bundle = (p && Array.isArray(p.bundle_items)) ? p.bundle_items.filter(c => c && c.sku).map(c => ({ sku: c.sku, qty: Number(c.qty) || 1 })) : [];
  modal._bundle = bundle;
  const bundleList = modal.querySelector('#pm-bundle-list');
  const bundleSum = modal.querySelector('#pm-bundle-sum');
  function bundleSumText() {
    let sum = 0; bundle.forEach(c => { const cp = productBySku(c.sku); if (cp) sum += (Number(cp.price) || 0) * (Number(c.qty) || 1); });
    bundleSum.textContent = bundle.length ? `Бүрэлдэхүүний нийт үнэ: ${fmtMoney(sum)} · Багцын нөөц: ${packageStock({ bundle_items: bundle })}` : '';
  }
  function renderBundle() {
    bundleList.innerHTML = bundle.length ? bundle.map((c, i) => {
      const cp = productBySku(c.sku);
      return `<div class="pm-bi-row" data-bi="${i}">
        <input class="pm-bi-name" list="pm-prod-list" value="${escapeHtml(cp ? cp.name : '')}" placeholder="Бараа сонгох">
        <input class="pm-bi-qty" type="number" min="1" value="${c.qty || 1}" title="Тоо">
        <button type="button" class="pm-bi-rm" data-birm="${i}" title="Хасах">×</button>
      </div>`;
    }).join('') : '<div class="pm-bundle-empty">Бараа нэмнэ үү</div>';
    bundleSumText();
  }
  renderBundle();
  // Багц / Үйлчилгээ харилцан үл нийцэх; үйлчилгээ бол нөөц/салбар хуваарь хэрэггүй
  const _svcEl = modal.querySelector('#pm-isservice');
  const _pkgEl = modal.querySelector('#pm-ispackage');
  const _stockBlk = modal.querySelector('.pm-branch');
  const _syncType = () => {
    modal.querySelector('#pm-bundle').hidden = !_pkgEl.checked;
    if (_stockBlk) _stockBlk.style.display = _svcEl.checked ? 'none' : '';
  };
  _pkgEl.onchange = () => { if (_pkgEl.checked) _svcEl.checked = false; _syncType(); };
  _svcEl.onchange = () => { if (_svcEl.checked) _pkgEl.checked = false; _syncType(); };
  _syncType();
  modal.querySelector('#pm-bundle-add').onclick = () => { bundle.push({ sku: '', qty: 1 }); renderBundle(); };
  bundleList.addEventListener('input', (e) => {
    const row = e.target.closest('.pm-bi-row'); if (!row) return; const i = +row.dataset.bi;
    if (e.target.classList.contains('pm-bi-name')) { const prod = productByName(e.target.value); bundle[i].sku = prod ? prod.sku : ''; }
    else if (e.target.classList.contains('pm-bi-qty')) { bundle[i].qty = Math.max(1, Number(e.target.value) || 1); }
    bundleSumText();
  });
  bundleList.addEventListener('click', (e) => {
    const rm = e.target.closest('[data-birm]'); if (!rm) return;
    bundle.splice(+rm.dataset.birm, 1); renderBundle();
  });
  // Бүтэн нөөц (түрээслэх боломжтой) — нийт − эвдэрсэн − засварт, шууд шинэчлэгдэнэ.
  const workingEl = modal.querySelector('#pm-working');
  function updateWorking() {
    const st = Number(modal.querySelector('#pm-stock').value) || 0;
    const br = Number(modal.querySelector('#pm-broken').value) || 0;
    const mn = Number(modal.querySelector('#pm-maintenance').value) || 0;
    workingEl.innerHTML = (br || mn) ? `✅ Түрээслэх боломжтой: <b>${Math.max(0, st - br - mn)}</b> ширхэг${br ? ` · <span style="color:var(--danger)">⚠ ${br} эвдэрсэн</span>` : ''}${mn ? ` · <span style="color:var(--warn)">🔧 ${mn} засварт</span>` : ''}` : '';
  }
  ['pm-stock', 'pm-broken', 'pm-maintenance'].forEach(id => modal.querySelector('#' + id)?.addEventListener('input', updateWorking));
  updateWorking();
  // Салбарын хуваарилалт — M-Event>0 бол сайтад түрээслэгдэнэ. M-Event = Нийт − Чимун − NOMAAD (авто).
  // Шинэ бараанд салбараа ИЛЭЭР сонготол (чип эсвэл гараар тоо) авто-бөглөхгүй, хадгалахыг блоклоно.
  const qmEl = modal.querySelector('#pm-qm'), qcEl = modal.querySelector('#pm-qc'), qnEl = modal.querySelector('#pm-qn'), qkEl = modal.querySelector('#pm-qk');
  const stockEl = modal.querySelector('#pm-stock'), branchStatus = modal.querySelector('#pm-branch-status');
  const _qkv = () => Number(qkEl && qkEl.value) || 0;   // катеринг (шинэ багана)
  let branchTouched = isEdit;
  modal._branchTouched = () => branchTouched;
  function updateBranch() {
    const qm = Number(qmEl.value) || 0;
    const sum = qm + (Number(qcEl.value) || 0) + (Number(qnEl.value) || 0) + _qkv();
    if (!branchTouched && !sum) {
      branchStatus.innerHTML = `<span style="color:var(--warn);font-weight:600;">⚠ Аль салбарт байхыг сонгоно уу</span>`;
      return;
    }
    branchStatus.innerHTML = `<span style="color:${qm > 0 ? 'var(--ok)' : 'var(--muted)'};font-weight:600;">${qm > 0 ? '✅ Сайтад түрээслэгдэнэ' : '🔒 Зөвхөн дотоод хөрөнгө — сайтад харагдахгүй'}</span>`;
  }
  function syncPickChips() {   // гараар тоо өөрчилбөл чипийн тодруулгыг таарууна
    const qm = Number(qmEl.value) || 0, qc = Number(qcEl.value) || 0, qn = Number(qnEl.value) || 0, qk = _qkv();
    modal.querySelectorAll('[data-brpick]').forEach(b => {
      const only = { m: qm > 0 && !qc && !qn && !qk, c: qc > 0 && !qm && !qn && !qk, n: qn > 0 && !qm && !qc && !qk }[b.dataset.brpick];
      b.classList.toggle('on', !!only);
    });
  }
  function fillMevent() {   // Нийт эсвэл Чимун/NOMAAD/Катеринг өөрчлөгдвөл M-Event = үлдэгдэл (салбар сонгосны дараа л)
    if (!branchTouched) { updateBranch(); return; }
    const st = Number(stockEl.value) || 0, qc = Number(qcEl.value) || 0, qn = Number(qnEl.value) || 0;
    qmEl.value = Math.max(0, st - qc - qn - _qkv()); updateBranch(); syncPickChips();
  }
  stockEl.addEventListener('input', fillMevent);
  [qcEl, qnEl, qkEl].filter(Boolean).forEach(el => el.addEventListener('input', () => { branchTouched = true; fillMevent(); }));
  qmEl.addEventListener('input', () => {   // M-Event гараар өөрчилвөл Нийт нөөцийг нийлбэрт тэнцүүлнэ
    branchTouched = true;
    stockEl.value = (Number(qmEl.value) || 0) + (Number(qcEl.value) || 0) + (Number(qnEl.value) || 0) + _qkv();
    updateWorking(); updateBranch(); syncPickChips();
  });
  modal.querySelectorAll('[data-brpick]').forEach(b => b.addEventListener('click', () => {
    branchTouched = true;
    const st = Math.max(1, Number(stockEl.value) || 0);
    stockEl.value = st;
    qmEl.value = b.dataset.brpick === 'm' ? st : 0;
    qcEl.value = b.dataset.brpick === 'c' ? st : 0;
    qnEl.value = b.dataset.brpick === 'n' ? st : 0;
    if (qkEl) qkEl.value = 0;
    updateWorking(); updateBranch(); syncPickChips();
  }));
  if (!isEdit) {   // Шинэ бараа — default салбар = 🏢 Чимун дотоод (шаардлагатай бол дараа сольж болно)
    branchTouched = true;
    const st = Math.max(1, Number(stockEl.value) || 0);
    qcEl.value = st; qmEl.value = 0; qnEl.value = 0; if (qkEl) qkEl.value = 0;
  }
  updateBranch(); syncPickChips();
  const close = () => modal.remove();
  modal.querySelector('#pm-cancel').onclick = close;
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  modal.querySelector('#pm-save').onclick = (e) => submitProductModal(modal, p, e.currentTarget);
  modal.classList.add('open');
  setTimeout(() => modal.querySelector('#pm-name')?.focus(), 50);
}

async function submitProductModal(modal, orig, btn) {
  const g = (id) => (modal.querySelector('#' + id)?.value || '').trim();
  const name = g('pm-name');
  if (!name) { showToast('Нэр оруулна уу', 'warn'); return; }
  const cat = g('pm-cat');
  const code = (orig && orig.code) || nextProductCode();   // засварт хэвээр, шинэд авто M-код
  let sku = g('pm-sku');
  if (!orig) sku = code;   // шинэ бараа: дотоод sku = код (M-xxx нэг ижил)
  const images = (modal._images || []).filter(Boolean);
  const isPkg = !!modal.querySelector('#pm-ispackage')?.checked;
  const isSvc = !isPkg && !!modal.querySelector('#pm-isservice')?.checked;
  const bundle = isPkg ? (modal._bundle || []).filter(c => c.sku) : [];
  if (isPkg && !bundle.length) { showToast('Багцад дор хаяж нэг бараа нэмнэ үү', 'warn'); return; }
  // Шинэ бараанд нэгж өртөг ЗААВАЛ (багц=бүрэлдэхүүнээс, үйлчилгээ=өртөггүй тул хасна)
  if (!orig && !isPkg && !isSvc && !(moneyVal(modal.querySelector('#pm-cost')) > 0)) {
    showToast('Нэгж өртөг заавал оруулна (худалдан авсан үнэ)', 'warn', 3500);
    modal.querySelector('#pm-cost')?.focus();
    return;
  }
  // Шинэ бараанд салбарын хуваарилалт ЗААВАЛ — аль салбарт хэдэн ширхэг байхыг сонгоно
  if (!orig && !isPkg && !isSvc) {
    const _qsum = (Number(modal.querySelector('#pm-qm')?.value) || 0) + (Number(modal.querySelector('#pm-qc')?.value) || 0) + (Number(modal.querySelector('#pm-qn')?.value) || 0) + (Number(modal.querySelector('#pm-qk')?.value) || 0);
    if (!_qsum) {
      showToast('Салбарын хуваарилалт: аль салбарт байхыг сонгоно уу', 'warn', 3500);
      modal.querySelector('#pm-branch-pick')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
  }
  const _qm = Number(modal.querySelector('#pm-qm')?.value) || 0;
  const _qc = Number(modal.querySelector('#pm-qc')?.value) || 0;
  const _qn = Number(modal.querySelector('#pm-qn')?.value) || 0;
  const _qk = Number(modal.querySelector('#pm-qk')?.value) || 0;
  const base = {
    name, name_en: g('pm-nameen') || null, category: cat, sku, code,   // sku === code === M-xxx
    price: moneyVal(modal.querySelector('#pm-price')), deposit: moneyVal(modal.querySelector('#pm-deposit')),
    stock: isPkg ? packageStock({ bundle_items: bundle }) : (_qm + _qc + _qn + _qk),
    broken: isPkg ? 0 : (Number(g('pm-broken')) || 0),
    maintenance: isPkg ? 0 : (Number(g('pm-maintenance')) || 0),
    photos: images, photo: images[0] || '',   // эхний зураг = нүүр
    description: modal.querySelector('#pm-desc').value,
    type: isPkg ? 'package' : (isSvc ? 'service' : (_qm > 0 ? 'rental' : 'asset')),   // Багц / Үйлчилгээ / M-Event>0=түрээс / асет
    qty_mevent: isPkg ? 0 : _qm, qty_chimun: isPkg ? 0 : _qc, qty_nomaad: isPkg ? 0 : _qn, qty_catering: isPkg ? 0 : _qk,
    bundle_items: bundle,
    all_categories: cat ? [cat] : ((orig && orig.all_categories) || []),
    variant_group: null, variant_label: null,   // хувилбар халагдсан — хадгалах бүрд цэвэрлэнэ
    source_url: g('pm-source') || null,
    media_url: g('pm-media') || null,
    supplier: g('pm-source') || null,
    purchase_date: g('pm-purchase') || null,
  };
  const product = orig ? { ...orig, ...base } : base;
  product.cost = moneyVal(modal.querySelector('#pm-cost'));
  btn.disabled = true;
  try {
    await saveProduct(product);   // каталог + өртөг → VPS Postgres (upsert)
    modal.remove();
  } catch (e) { showToast('Алдаа: ' + e.message, 'error'); btn.disabled = false; }
}

function attachProductsHandlers() {
  // Шүүлтүүр таб — Бүгд / Түрээсийн / Хөрөнгө
  document.querySelectorAll('[data-prodfilter]').forEach(b => {
    b.onclick = () => { state.prodFilter = b.dataset.prodfilter; render(); };
  });
  // (Агуулахын доод салбар таб хасагдсан — толгойн ленз ГАНЦ удирдлага.)
  // Ангилал шүүлт + эрэмбэ
  document.getElementById('prod-filters')?.addEventListener('toggle', (e) => { state.prodFiltersOpen = e.target.open; });
  document.getElementById('prod-filters-clear')?.addEventListener('click', () => {
    state.prodCategory = 'all'; state.prodMissing = 'all'; state.prodSort = 'name'; render();
  });
  document.getElementById('prod-cat')?.addEventListener('change', (e) => { state.prodCategory = e.target.value; render(); });
  document.getElementById('prod-missing')?.addEventListener('change', (e) => { state.prodMissing = e.target.value; render(); });
  document.getElementById('prod-sort')?.addEventListener('change', (e) => { state.prodSort = e.target.value; render(); });
  // Салбар хооронд шилжүүлэх (мөр нээхээс сэргийлж stopPropagation)
  document.querySelectorAll('[data-transfer]').forEach(b => {
    b.addEventListener('click', (e) => { e.stopPropagation(); openTransferModal(b.dataset.transfer); });
  });
  // Улирал хаалт — NOMAAD-ийн бүх нөөцийг M-Event руу
  document.getElementById('prod-return-nomaad')?.addEventListener('click', () => bulkReturnBranch('nomaad', 'mevent'));
  document.getElementById('prod-clear-variants')?.addEventListener('click', () => bulkClearVariants());
  document.getElementById('prod-fill-nameen')?.addEventListener('click', () => bulkFillNameEn());
  // Хайлт — DOM filter (focus алдахгүй, дахин render хийхгүй)
  const s = document.getElementById('prod-search');
  if (s) s.oninput = (e) => {
    const q = e.target.value.toLowerCase().trim();
    state.productSearch = e.target.value;
    let n = 0;
    document.querySelectorAll('.prod-row').forEach(row => {
      const show = !q || (row.dataset.search || '').includes(q);
      row.style.display = show ? '' : 'none';
      if (show) n++;
    });
    const c = document.getElementById('prod-count');
    // <b>-г хадгална (мета мөр тоог тодоор харуулдаг) — textContent бол устгана
    if (c) c.innerHTML = `<b>${n}</b> бараа${q ? ' <span class="prod-meta-dim">(шүүсэн)</span>' : ''}`;
  };
  // Мөр дээр дарж дэлгэрэнгүй/засах модал нээх
  document.querySelectorAll('[data-product-open]').forEach(row => {
    row.addEventListener('click', () => {
      const v = row.dataset.productOpen;
      const p = (state.products || []).find(x => String(x.id) === v || String(x.sku) === v);
      if (p) openProductModal(p);
    });
  });
  // Шинэ бараа → хоосон модал
  document.getElementById('prod-new')?.addEventListener('click', () => openProductModal(null));
  document.getElementById('prod-groups')?.addEventListener('click', () => openCategoryGroupsModal());
  // QR скан → бараа таних
  document.getElementById('prod-scan')?.addEventListener('click', () => openScanner());
}

/* ─── CEO Dashboard ───────────────────────────────────────
   Үндсэн KPI болон график.
   - Task статусын pie/donut
   - Сарын санхүүгийн хүсэлтийн дүн
   - Ажилтан тус бүрийн идэвхтэй ажлын тоо
   - Хоцорсон таскын тоо
   Бүх chart нь inline SVG — гадны library хэрэггүй.
   CEO бус хэрэглэгчид зөвхөн хувийн KPI хэсэг (renderPersonalKPI) харагдана. */
/* Санхүүгийн хүсэлтийн төлбөрийн үе шат — НЭГ эх сурвалж (тайлангийн карт, мөрийн тэмдэг,
   Excel экспорт бүгд үүгээр). Батлагдсан хүсэлтийг шилжүүлсэн/шилжүүлээгүй/дууссанаар ялгана.
   key: pending | untransferred | transferred | fdone | rejected | deferred */
function finStage(t) {
  const dec = t.decision || 'pending';
  if (dec === 'rejected') return { key: 'rejected',      label: 'Татгалзсан',    mark: '✗',  color: 'var(--danger)' };
  if (dec === 'deferred') return { key: 'deferred',      label: 'Хойшлуулсан',   mark: '🕐', color: 'var(--warn)' };
  if (dec !== 'approved')  return { key: 'pending',       label: 'Хүлээгдэж буй', mark: '⏳', color: 'var(--warn)' };
  // Батлагдсан → төлбөрийн үе шат
  if (t.status === 'done') {
    // Дууссан хүсэлтийг баримтаар нь ялгана (аудит — нээлгүйгээр баримтгүйг шууд харах).
    if (t.close_type === 'дутуу')                          return { key: 'fdone', label: 'Дууссан · дутуу',     mark: '⚠',  color: 'var(--warn)' };
    if (t.close_type === 'хуулгаар')                       return { key: 'fdone', label: 'Дууссан · хуулгаар',  mark: '🏦', color: 'var(--ok)' };
    if (t.close_type === 'захирал')                        return { key: 'fdone', label: 'Дууссан · захирал',   mark: '👤', color: 'var(--ok)' };
    if (t.close_type === 'баримтгүй' || (t.has_receipt === false && t.close_type !== 'шилжүүлгээр'))
                                                           return { key: 'fdone', label: 'Дууссан · баримтгүй',  mark: '📝', color: 'var(--warn)' };
    return                                                        { key: 'fdone', label: 'Дууссан',             mark: '✓',  color: 'var(--ok)' };
  }
  if (t.executed_at)       return { key: 'transferred',   label: 'Шилжүүлсэн',    mark: '💵', color: 'var(--primary)' };
  return                          { key: 'untransferred', label: 'Шилжүүлээгүй',  mark: '💸', color: 'var(--warn)' };
}

/* ═══════════════════════════════════════════════════════════════════════
   ТҮРЭЭСИЙН ТҮҮХ (түүхэн аналитик) — зөвхөн CEO
   2024–2026 түүхэн түрээсийн бүрэн түүхийг VPS Postgres-ийн rh_v_*
   аналитик view-уудаас (PostgREST, anon SELECT) уншиж шийдвэр гаргалтад
   зориулсан самбараар харуулна. Дата статик (түүх) тул view нээх үед НЭГ
   удаа lazy-load хийнэ (polling-д ороогүй).
   Schema+backfill: postgres-migration/bq_01_schema.sql .. bq_07_*.sql
═══════════════════════════════════════════════════════════════════════ */
async function loadHistory(force) {
  if (state._bqLoading) return;
  if (state.history && !state.history.error && !force) return;
  if (!DB_ANON_KEY) { state.history = { error: 'no-key' }; if (typeof render === 'function') render(); return; }
  state._bqLoading = true;
  const H = { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + DB_ANON_KEY };
  const get = async (view, qs) => {
    const r = await fetchWithTimeout(`${DB_URL}/rest/v1/${view}?select=*${qs || ''}`, { headers: H }, 20000);
    if (!r.ok) throw new Error(view + ' HTTP ' + r.status);
    return r.json();
  };
  try {
    // ⭐ НЭГ ЭХ СУРВАЛЖ: KPI/орлого/сар + бараа/ROI/ашиглалт/харилцагч бүгд app_orders-оос
    // (нэгдсэн амьд захиалга). Бараа/харилцагчийг захиалгаас шууд тооцоолно → KPI-тай тулгарна,
    // nomaad camp/давхардал/хуучирсан snapshot асуудал арилна. Төлбөрийн хэлбэр л bq_payments-аас
    // (app_orders-д migrate үед method ороогүй) — Booqable түүхэн гэж шошголно.
    const rawOrders = fetchWithTimeout(
      `${DB_URL}/rest/v1/app_orders?select=id,customer,status,starts_at,stops_at,total_mnt,paid_mnt,items&status=not.in.(draft,canceled)&limit=3000`,
      { headers: H }, 25000).then(r => r.ok ? r.json() : []).catch(() => []);
    // Ангиллын толь — амьд каталогаас (бараа бүлэглэхэд ашиглана)
    const rawProducts = fetchWithTimeout(
      `${DB_URL}/rest/v1/products?select=sku,name,category&limit=2000`,
      { headers: H }, 20000).then(r => r.ok ? r.json() : []).catch(() => []);
    const [summary, monthly, methods, orders, roiFix, prods] = await Promise.all([
      get('rh_v_summary'),
      get('rh_v_monthly_revenue', '&order=month.asc'),
      get('rh_v_payment_method'),
      rawOrders,
      // Эзэмшсэн тоо (Booqable stock_counts) + нэгж өртөг: {bySku,byName → {o,c}}. ROI-д ашиглана.
      get('app_config', '&key=eq.rh_roi_fix&select=value').then(r => r[0] && r[0].value).catch(() => null),
      rawProducts,
    ]);
    const comp = _histCompute(orders || [], roiFix, _histCatResolver(prods || []));
    state.history = {
      summary: summary[0] || null,
      monthly: monthly || [],
      methods: methods || [],
      products: comp.products,
      customers: comp.customers,
      usage: comp.usage,
      services: comp.services,
      roi: comp.roi,
      roiFix: roiFix || null,
      unknownRev: comp.unknownRev,
      unknownCnt: comp.unknownCnt,
      namedCustomers: comp.customers.length,
      ordersCount: (orders || []).length,
      loadedAt: Date.now(),
    };
  } catch (e) {
    console.warn('loadHistory', e);
    // Хүснэгт/view үүсээгүй (SQL ачаалаагүй) бол энд унана.
    state.history = { error: 'load', msg: String(e.message || e) };
  } finally {
    state._bqLoading = false;
    if (typeof render === 'function') render();
  }
}

// түүхэн түүх захиалгуудыг lazy татна (үндсэн Захиалга самбарын архив). rh_v_orders view.
// state.bqOrders — top-level (Түрээсийн түүх самбар нээгээгүй ч ажиллана).
async function loadOrdersData() {
  // Захиалга бүр одоо app_orders-т НЭГДСЭН (түүхэн архивыг app_orders руу migrate хийсэн).
  // bqOrders-ийг хоосон байлгана → төлбөр/статусын routing бүгд app_orders руу орно.
  // Жагсаалт/авлага/дашборд/badge бүгд state.appOrders уншина. Аналитик (rh_v_* view) тусдаа.
  state.bqOrders = [];
  return loadAppOrders();
}

// Нэг захиалгын бараа (мөр)-ийг шаардахад татна, кэшилнэ. rh_v_order_items view.
async function loadOrderItems(orderId) {
  state.bqOrderItems = state.bqOrderItems || {};
  if (state.bqOrderItems[orderId]) return state.bqOrderItems[orderId];
  try {
    const r = await fetchWithTimeout(`${DB_URL}/rest/v1/rh_v_order_items?order_id=eq.${encodeURIComponent(orderId)}&select=*`,
      { headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + DB_ANON_KEY } }, 15000);
    state.bqOrderItems[orderId] = r.ok ? await r.json() : [];
  } catch (e) { console.warn('loadOrderItems', e); state.bqOrderItems[orderId] = []; }
  return state.bqOrderItems[orderId];
}

// Захиалгын баримт (нэхэмжлэх/үнийн санал/гэрээ) — lazy, rh_v_documents (PII-гүй).
async function loadOrderDocs(orderId) {
  state.bqDocuments = state.bqDocuments || {};
  if (state.bqDocuments[orderId]) return state.bqDocuments[orderId];
  try {
    const r = await fetchWithTimeout(`${DB_URL}/rest/v1/rh_v_documents?order_id=eq.${encodeURIComponent(orderId)}&select=*`,
      { headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + DB_ANON_KEY } }, 15000);
    state.bqDocuments[orderId] = r.ok ? await r.json() : [];
  } catch (e) { console.warn('loadOrderDocs', e); state.bqDocuments[orderId] = []; }
  return state.bqDocuments[orderId];
}

const BQ_DOC_TYPE = {
  invoice:  { icon: '💵', label: 'Нэхэмжлэх' },
  quote:    { icon: '📝', label: 'Үнийн санал' },
  contract: { icon: '📋', label: 'Гэрээ' },
};
const BQ_DOC_STATUS = {
  paid:           { label: 'Төлсөн',           cls: 'ok' },
  partially_paid: { label: 'Хэсэгчилсэн',      cls: 'warn' },
  payment_due:    { label: 'Төлбөр хүлээж буй', cls: 'warn' },
  overpaid:       { label: 'Илүү төлсөн',       cls: 'ok' },
  revised:        { label: 'Шинэчилсэн',        cls: 'muted' },
  confirmed:      { label: 'Баталсан',          cls: 'ok' },
  draft:          { label: 'Ноорог',            cls: 'muted' },
  sent:           { label: 'Илгээсэн',          cls: '' },
};
// Захиалгын баримтуудыг HTML болгоно (төрлөөр эрэмбэлж: гэрээ→үнийн санал→нэхэмжлэх).
function bqDocsHtml(docs) {
  if (!docs || !docs.length) return '<div class="order-meta">баримт алга</div>';
  const ORD = { contract: 0, quote: 1, invoice: 2 };
  const sorted = docs.slice().sort((a, b) =>
    (ORD[a.document_type] ?? 9) - (ORD[b.document_type] ?? 9)
    || String(b.doc_date || '').localeCompare(String(a.doc_date || '')));
  const rows = sorted.map(d => {
    const t = BQ_DOC_TYPE[d.document_type] || { icon: '📄', label: d.document_type || 'Баримт' };
    const s = BQ_DOC_STATUS[d.status] || { label: d.status || '', cls: '' };
    const date = d.doc_date ? String(d.doc_date).slice(0, 10) : '';
    const total = Number(d.total_mnt) || 0, paid = Number(d.paid_mnt) || 0;
    const isInv = d.document_type === 'invoice';
    return `<div class="bq-doc${d.revised ? ' bq-doc-revised' : ''}">
      <span class="bq-doc-t">${t.icon} ${escapeHtml(t.label)}${d.prefix_number ? ' ' + escapeHtml(d.prefix_number) : ''}</span>
      <span class="bq-doc-m">${date}${total ? ' · ' + fmtMoney(total) : ''}${isInv && paid && paid !== total ? ' · төл. ' + fmtMoney(paid) : ''}${d.document_type === 'contract' && d.signed ? ' · ✍' : ''}</span>
      ${s.label ? `<span class="bq-doc-s ${s.cls}">${escapeHtml(s.label)}</span>` : ''}
    </div>`;
  }).join('');
  return `<div class="bq-docs">${rows}</div>`;
}

// түүхэн түрээсийн 6 төлөв — нэр/өнгө/icon. Дараалал: Ноорог→Захиалсан→Эхэлсэн→Дууссан→Архивласан→Цуцалсан.
// Дэвсгэр (light) + бараан текст (WCAG AA контраст) + зүүн талын тод цэг.
const BQ_STATUS = {
  draft:       { label: 'Ноорог',        dot: '#6B7280', bg: '#F3F4F6', tx: '#374151' },
  reserved:    { label: 'Захиалсан',     dot: '#D97706', bg: '#FEF3C7', tx: '#92400E' },
  prepared:    { label: 'Бэлдсэн',       dot: '#0891B2', bg: '#CFFAFE', tx: '#155E75' },
  delivering:  { label: 'Хүргэгдэж байна', dot: '#7C3AED', bg: '#EDE9FE', tx: '#5B21B6' },
  rented:      { label: 'Түрээсэнд',     dot: '#2563EB', bg: '#DBEAFE', tx: '#1E40AF' },
  returning:   { label: 'Буцаалт замд', dot: '#DB2777', bg: '#FCE7F3', tx: '#9D174D' },
  returned:    { label: 'Дууссан', dot: '#16A34A', bg: '#DCFCE7', tx: '#15803D' },
  archived:    { label: 'Архивласан',    dot: '#475569', bg: '#E2E8F0', tx: '#334155' },
  canceled:    { label: 'Цуцалсан',      dot: '#DC2626', bg: '#FEE2E2', tx: '#B91C1C' },
  deleted:     { label: 'Устгасан',      dot: '#9CA3AF', bg: '#F3F4F6', tx: '#6B7280' },
  // Хуучин төлөв (түүхэн захиалга рендерлэхэд)
  preparation: { label: 'Бэлтгэл',       dot: '#7C3AED', bg: '#EDE9FE', tx: '#5B21B6' },
  cleaning:    { label: 'Бэлдсэн',       dot: '#0891B2', bg: '#CFFAFE', tx: '#155E75' },
  ready:       { label: 'Цэвэрлэсэн',  dot: '#0D9488', bg: '#CCFBF1', tx: '#0F766E' },
  started:     { label: 'Гарсан',        dot: '#2563EB', bg: '#DBEAFE', tx: '#1E40AF' },
  stopped:     { label: 'Дууссан',       dot: '#16A34A', bg: '#DCFCE7', tx: '#15803D' },
};
const BQ_STATUS_ORDER = ['draft', 'reserved', 'prepared', 'rented', 'returned', 'stopped', 'archived', 'canceled', 'deleted'];
// Хуучин/хассан (legacy) төлөвийг одоогийн урсгалын төлөв рүү буулгана — эс бол тэдгээр захиалга
// ямар ч табд таарахгүй зөвхөн "Бүгд"-д харагдана. delivering/returning-г хассан (зам-дундын микро-төлөв).
const BQ_LEGACY_MAP = { preparation: 'prepared', cleaning: 'prepared', ready: 'prepared', started: 'rented', delivering: 'rented', returning: 'returned' };
// Лайфциклийн дараагийн алхам. Ноорог→Захиалсан нь ТӨЛБӨРӨӨР шилжинэ.
// ⚠ Урсгал нь хүргэлт/очиж авахаар САЛААЛНА — тиймээс статик map биш orderNextStep(o) ашиглана.
// Хүргэлттэй:  Захиалсан→[Бэлтгэх]→Цэвэрлэгээ→[Цэвэрлсэн]→Гарахад бэлэн→[Агуулахаас гарсан]→Гарсан→[Хүргэж өгсөн]→Дууссан
// Очиж авах:   … Гарахад бэлэн→[Олгосон]→Дууссан
// Хуучин захиалгад хүргэлт нь ТУСДАА бараа мөр болж орсон (⟦DLV⟧ token/хаяггүй).
// Нэрээр таниж эдгээрийг ч хүргэлттэй гэж үзнэ (зөвхөн хүргэлт/тээвэр — суурилуулалт/оператор БИШ).
const _DELIVERY_ITEM_RE = /хүргэл|тээвэр|достав|deliver/i;
function orderHasDeliveryItem(o) {
  const items = (o && o.items) || [];
  return Array.isArray(items) && items.some(it => _DELIVERY_ITEM_RE.test(String((it && (it.name || it.title || it.product)) || '')));
}
function isDeliveryOrder(o) {
  const d = (typeof parseDelivery === 'function') ? parseDelivery(o && o.note) : null;
  if (d && (d.zone === 'city' || d.zone === 'out')) return true;   // DLV token хот/гадна
  if (String((o && (o.delivery_address || o.customer_address)) || '').trim()) return true;   // хаягтай
  return orderHasDeliveryItem(o);   // хуучин захиалга — хүргэлт нь бараа мөр
}
// Хялбаршуулсан урсгал: Захиалсан → Бэлдсэн → Түрээсэнд(гарсан) → Буцаан авсан → Архив.
// (delivering/returning зам-дундын микро-төлөвүүдийг хассан; хуучин төлөв legacy map-аар буулгагдана.)
function orderNextStep(o) {
  const st = String((o && o.status) || '');
  switch (st) {
    case 'reserved':
    case 'preparation':
    case 'cleaning':
    case 'ready':       return { to: 'prepared', label: '🧰 Бэлдэх',   cap: 'orders.prepare' };
    case 'prepared':
    case 'delivering':  return { to: 'rented',   label: '📦 Гаргах / Хүргэх', cap: 'orders.dispatch' };
    case 'rented':
    case 'started':
    case 'returning':   return { to: 'returned', label: '📥 Буцаан авах', cap: 'orders.dispatch' };
    case 'returned':
    case 'stopped':     return { to: 'archived', label: '🗄 Архивлах', cap: 'orders.advance' };
    default: return null;
  }
}
// Хуучин статик map (легаси/bq картын fallback) — orderNextStep-ийн хүргэлт хувилбар
const BQ_NEXT = {
  reserved:    { to: 'cleaning', label: '🧰 Бэлтгэх' },
  preparation: { to: 'cleaning', label: '🧰 Бэлтгэх' },
  cleaning:    { to: 'ready',    label: '🧹 Цэвэрлсэн' },
  ready:       { to: 'started',  label: '📦 Агуулахаас гарсан' },
  started:     { to: 'stopped',  label: '🚚 Хүргэж өгөх' },
  stopped:     { to: 'archived', label: '🗄 Архивлах' },
};

// ── Дамжлагын АВТОМАТ ажил — эрх эзэмшигчид даалгавар үүсгэж, зургаар баталгаажуулна ──
// Шат бүрд ажил хийх эрх (cap) + fallback роль + үйлдлийн нэр. Захиалга шат руу орох бүрд ажил үүснэ.
const STAGE_AUTOTASK = {
  reserved:   { cap: 'orders.clean',    role: /цэвэрл/i,              verb: '🧹 Захиалга цэвэрлэх' },
  prepared:   { cap: 'orders.dispatch', role: /нярав|агуулах/i,       verb: '📦 Хүлээлгэн өгөх' },
  delivering: { cap: 'orders.deliver',  role: /хүргэ|жолооч|түгээ/i,  verb: '🚚 Хүргэж өгөх' },
  rented:     { cap: 'orders.deliver',  role: /хүргэ|жолооч|түгээ/i,  verb: '↩ Түрээс дуусахад буцаан авах', due: 'stops_at' },
  returning:  { cap: 'orders.dispatch', role: /нярав|агуулах/i,       verb: '📦 Агуулахад хүлээн авах',          due: 'stops_at' },
};
// Эрх (cap)-ыг ТОДОРХОЙ эзэмшигчид (role_perms/member_perms) — CEO-ийн бүх эрхийг ОРУУЛАХГҮЙ (эс бол бүх ажил CEO-д очно)
function membersWithCap(cap) {
  const out = [];
  for (const m of (typeof TEAM !== 'undefined' ? TEAM : [])) {
    const key = personKey(m);
    const mp = state.memberPerms && state.memberPerms[key];
    if (mp && Object.prototype.hasOwnProperty.call(mp, cap)) { if (mp[cap]) out.push(key); continue; }
    const rp = state.rolePerms && state.rolePerms[normRole(m.role)];
    if (rp && rp[cap]) out.push(key);
  }
  return out;
}
// Ажлын id-д захиалга+шат кодлоно (reload-д хадгалагдана, тусдаа багана хэрэггүй)
function stageTaskId(orderId, toStatus) { return 'ordstage__' + orderId + '__' + toStatus; }
function parseStageTaskId(id) { const p = String(id || '').split('__'); return (p[0] === 'ordstage' && p.length === 3) ? { orderId: p[1], toStatus: p[2] } : null; }
// Захиалга тухайн шатанд орох үед хариуцагчид ажил үүсгэнэ (давхардахгүй)
function ensureStageTask(o) {
  if (!o || !o.id) return;
  const cfg = STAGE_AUTOTASK[String(o.status || '')]; if (!cfg) return;
  const next = orderNextStep(o); if (!next) return;
  const id = stageTaskId(o.id, next.to);
  if ((state.tasks || []).some(t => t.id === id)) return;   // аль хэдийн үүссэн
  let assignee = membersWithCap(cfg.cap)[0] || findMemberEmailByRole(cfg.role, '');
  const t = {
    id, title: `${cfg.verb} · захиалга #${o.number ?? ''}${o.customer ? ' — ' + o.customer : ''}`,
    branch: 'm-event', project: '', assignee: assignee || '', due: (cfg.due === 'stops_at' ? (o.stops_at || o.starts_at) : o.starts_at) || '',
    priority: 'high', status: 'open', requires_photo: true,
    createdBy: state.me || getCEOEmail(), created: Date.now(), comments: [], activity: [],
  };
  try { saveTask(t); } catch (e) { console.warn('ensureStageTask', e); }
}
// Ажил (зурагтай) дуусахад холбоотой захиалгыг дараагийн шатанд шилжүүлнэ
async function advanceOrderFromTask(task) {
  const p = parseStageTaskId(task && task.id); if (!p) return;
  const o = (state.appOrders || []).find(x => String(x.id) === String(p.orderId)); if (!o) return;
  if (String(o.status) === p.toStatus) return;              // аль хэдийн шилжсэн
  const next = orderNextStep(o); if (!next || next.to !== p.toStatus) return;   // зөвхөн зөв дараагийн алхам
  // Ажлын зургийг захиалгын stage_meta-д хуулж бүх ажилтанд харагдуулна
  const act = stageActionFor(String(o.status || ''), p.toStatus);
  const sm = JSON.parse(JSON.stringify((o.stage_meta && typeof o.stage_meta === 'object') ? o.stage_meta : {}));
  const photos = (task.completion_photos || []).filter(Boolean);
  if (photos.length) sm[act.key] = Object.assign({}, sm[act.key], { photos, by: task.assignee || state.me, at: new Date().toISOString() });
  await bqUpdateStatus(o.id, p.toStatus, { stageMeta: photos.length ? sm : undefined, toast: `Захиалга #${o.number ?? ''}: ${(BQ_STATUS[p.toStatus] || {}).label || ''} ✓`, byTask: true });
}

// Дамжлагын шат: (from>to) → үйлдэл + өмнөх шат (үнэлэх). Товч бүрд зураг + өмнөхийн үнэлгээ
const STAGE_ACTION = {
  'reserved>cleaning':    { key: 'prepare',  label: 'Бэлдэх',                q: 'Захиалга зөв, бүрэн бэлдэгдсэн үү?' },
  'preparation>cleaning': { key: 'prepare',  label: 'Бэлдэх',                q: 'Захиалга зөв, бүрэн бэлдэгдсэн үү?' },
  'cleaning>ready':       { key: 'clean',    label: 'Цэвэрлэх',              q: 'Цэвэрлэгээ хэр чанартай хийгдсэн бэ?' },
  'ready>delivering':     { key: 'dispatch', label: 'Агуулахаас гаргах',     q: 'Ачаа бүрэн, зөв ачигдсан уу?' },
  'ready>rented':         { key: 'dispatch', label: 'Агуулахаас гаргах',     q: 'Захиалга бүрэн, зөв өгсөн үү?' },
  'prepared>delivering':  { key: 'dispatch', label: 'Агуулахаас гаргах',     q: 'Ачаа бүрэн, зөв ачигдсан уу?' },
  'prepared>rented':      { key: 'dispatch', label: 'Агуулахаас гаргах',     q: 'Захиалга бүрэн, зөв өгсөн үү?' },
  'delivering>rented':    { key: 'deliver',  label: 'Хүргэж өгөх',           q: 'Хүргэлт цаг хугацаандаа, бүрэн хүрсэн үү?' },
  'rented>returning':     { key: 'retstart', label: 'Буцааж авахаар гарах',  q: 'Бараа бүрэн бүтэн байна уу?' },
  'rented>returned':      { key: 'received', label: 'Буцаан хүлээж авах',     q: 'Бараа гэмтэлгүй, бүрэн буцаж ирсэн үү?' },
  'started>returning':    { key: 'retstart', label: 'Буцааж авахаар гарах',  q: 'Бараа бүрэн бүтэн байна уу?' },
  'started>returned':     { key: 'received', label: 'Буцаан хүлээж авах',     q: 'Бараа гэмтэлгүй, бүрэн буцаж ирсэн үү?' },
  'returning>returned':   { key: 'received', label: 'Агуулахад хүлээн авах',  q: 'Бараа гэмтэлгүй, бүрэн ирсэн үү?' },
  'returned>archived':    { key: 'archive',  label: 'Архивлах',              q: null },
  'stopped>archived':     { key: 'archive',  label: 'Архивлах',              q: null },
};
function stageActionFor(from, to) { return STAGE_ACTION[from + '>' + to] || { key: to, label: (BQ_STATUS[to] || {}).label || to, q: null }; }
const STAGE_META_LABEL = { prepare: '🧰 Бэлдсэн', clean: '🧹 Цэвэрлэгээ', dispatch: '📦 Ачилт (жолоочид)', handover: '🤝 Хүлээлгэн өгөлт', deliver: '🚚 Хүргэлт', retstart: '↩ Буцаалт эхэлсэн', received: '📥 Буцаан хүлээн авсан', archive: '🗄 Архив' };
// Шатны цаг форматлах — бүтэн цагтай бол огноо+цаг (орон нутгийн), эс бол зөвхөн огноо
function _stageTimeFmt(atISO) {
  const s = String(atISO || ''); if (!s) return '';
  if (!/T\d/.test(s)) return s.slice(0, 10).replace(/-/g, '.');
  const d = new Date(s); if (isNaN(d)) return s.slice(0, 10).replace(/-/g, '.');
  return `${d.getFullYear()}.${_pad2(d.getMonth() + 1)}.${_pad2(d.getDate())} ${_pad2(d.getHours())}:${_pad2(d.getMinutes())}`;
}
// Товлосон хугацаанд өгсөн/авсан уу — өгөх шат→starts_at, авах шат→stops_at (огноо+цаг note-оос)
function _stageTiming(k, atISO, o) {
  if (!/T\d/.test(String(atISO || ''))) return '';
  const at = Date.parse(atISO); if (isNaN(at)) return '';
  const isOut = ['dispatch', 'deliver', 'handover'].includes(k), isBack = ['retstart', 'received'].includes(k);
  if (!isOut && !isBack) return '';
  const t = (typeof parseOrderTimes === 'function' ? parseOrderTimes(o.note) : null) || { sh: 9, eh: 9 };
  const dateStr = String((isOut ? o.starts_at : o.stops_at) || '').slice(0, 10); if (!dateStr) return '';
  const sched = Date.parse(`${dateStr}T${_pad2(isOut ? t.sh : t.eh)}:00:00`); if (isNaN(sched)) return '';
  const diffH = Math.round((at - sched) / 3600000), verb = isOut ? 'өгсөн' : 'авсан';
  if (diffH <= 0) return ` · <span style="color:var(--ok);font-weight:600;">✓ хугацаандаа ${verb}${diffH <= -2 ? ` (${-diffH}ц эрт)` : ''}</span>`;
  return ` · <span style="color:var(--danger);font-weight:600;">⚠ ${diffH}ц хоцорч ${verb}</span>`;
}
// Дамжлагын зураг + үнэлгээ — БҮХ ажилтанд харагдана (картын доор)
function stageMetaHtml(o) {
  const sm = o && o.stage_meta;
  if (!sm || typeof sm !== 'object') return '';
  const keys = ['prepare', 'clean', 'dispatch', 'handover', 'deliver', 'retstart', 'received'].filter(k => sm[k] && ((sm[k].photos && sm[k].photos.length) || sm[k].rating || sm[k].by));
  if (!keys.length) return '';
  return `<div class="order-stagemeta">${keys.map(k => {
    const e = sm[k]; const photos = (e.photos || []).filter(Boolean);
    const stars = e.rating ? `<span class="sm-stars" title="${e.ratedBy ? escapeHtml((memberName(e.ratedBy) || e.ratedBy) + ' үнэлэв') : ''}">${'★'.repeat(e.rating)}<span style="color:var(--border-strong);">${'★'.repeat(5 - e.rating)}</span></span>` : '';
    const _ph = photos.length ? `<div class="sm-photos">${photos.map(u => `<img src="${escapeHtml(driveThumbUrl(u, 120))}" data-stagephoto="${escapeHtml(u)}" loading="lazy" referrerpolicy="no-referrer" />`).join('')}</div>` : '';
    const _head = `<div class="sm-head">${STAGE_META_LABEL[k] || k}${e.by ? ` · <b>${escapeHtml(memberName(e.by) || e.by)}</b>` : ''}${e.at ? ` · <span style="color:var(--muted);">${_stageTimeFmt(e.at)}</span>` : ''}${_stageTiming(k, e.at, o)}${stars ? ' · ' + stars : ''}</div>`;
    const _cmt = e.comment ? `<div class="sm-comment">💬 ${escapeHtml(e.comment)}</div>` : '';
    return `<div class="sm-row">${_ph}<div class="sm-body">${_head}${_cmt}</div></div>`;
  }).join('')}</div>`;
}
function openStagePhoto(url) {
  const ov = document.createElement('div'); ov.className = 'modal-bg open'; ov.style.zIndex = '10001';
  ov.innerHTML = `<div style="max-width:96%;max-height:94vh;display:flex;align-items:center;justify-content:center;"><img src="${escapeHtml(driveThumbUrl(url, 1400))}" referrerpolicy="no-referrer" style="max-width:100%;max-height:94vh;border-radius:8px;box-shadow:0 4px 24px rgba(0,0,0,.4);" /></div>`;
  ov.onclick = () => ov.remove();
  document.body.appendChild(ov);
}

// Товч дарахад — зураг (ЗААВАЛ) + өмнөх шатны үнэлгээ (ЗААВАЛ, сэтгэгдэл заавал биш)
function openStageAdvanceModal(oid, to) {
  const o = (state.appOrders || []).find(x => String(x.id) === String(oid)); if (!o) return;
  const act = stageActionFor(String(o.status || ''), to);
  const needPhoto = act.key !== 'archive';
  const q = act.q;
  const modal = document.createElement('div');
  modal.className = 'modal-bg open'; modal.style.zIndex = '9500';
  modal.innerHTML = `<div class="modal" style="max-width:460px;width:96%;max-height:92vh;overflow:auto;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><h2 style="margin:0;font-size:16px;">${escapeHtml(act.label)} · #${o.number ?? ''}</h2><button class="btn" id="sa-close" style="padding:5px 10px;">✕</button></div>
    ${needPhoto ? `<div style="font-size:12.5px;font-weight:700;margin-bottom:5px;">📷 Гүйцэтгэлийн зураг <span style="color:var(--danger);">*</span></div>
      <div id="sa-photos" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:6px;margin-bottom:6px;"></div>
      <label class="btn" for="sa-photo-input" style="display:block;text-align:center;border:2px dashed var(--accent,#7c3aed);border-radius:10px;padding:11px;cursor:pointer;margin-bottom:4px;">📷 Зураг оруулах / авах</label>
      <input id="sa-photo-input" type="file" accept="image/*" capture="environment" hidden>
      <div id="sa-photo-status" style="font-size:11px;color:var(--muted);margin-bottom:12px;"></div>` : ''}
    ${q ? `<div style="font-size:12.5px;font-weight:700;margin-bottom:2px;">⭐ ${escapeHtml(q)} <span style="color:var(--danger);">*</span></div>
      <div id="sa-stars" style="font-size:34px;letter-spacing:5px;margin:2px 0 4px;user-select:none;">${[1, 2, 3, 4, 5].map(i => `<span data-star="${i}" style="cursor:pointer;color:var(--border-strong);">★</span>`).join('')}</div>
      <textarea id="sa-comment" rows="2" placeholder="Сэтгэгдэл / шалтгаан (заавал биш)" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--panel);color:var(--text);margin-bottom:12px;font-size:13px;"></textarea>` : ''}
    <div style="display:flex;gap:8px;justify-content:flex-end;"><button class="btn" id="sa-cancel">Болих</button><button class="btn btn-primary" id="sa-submit" disabled>✓ Баталгаажуулах</button></div>
  </div>`;
  document.body.appendChild(modal);
  const $ = s => modal.querySelector(s);
  const close = () => modal.remove();
  $('#sa-close').onclick = close; $('#sa-cancel').onclick = close;
  modal.addEventListener('click', e => { if (e.target === modal) close(); });
  const photos = []; let rating = 0;
  const validate = () => { $('#sa-submit').disabled = !((!needPhoto || photos.length > 0) && (!q || rating > 0)); };
  if (needPhoto) {
    const renderPhotos = () => {
      $('#sa-photos').innerHTML = photos.map((u, i) => `<div style="position:relative;aspect-ratio:1;border-radius:8px;overflow:hidden;border:1px solid var(--border);"><img src="${escapeHtml(driveThumbUrl(u, 200))}" style="width:100%;height:100%;object-fit:cover;"><button data-prm="${i}" type="button" style="position:absolute;top:2px;right:2px;width:20px;height:20px;border:none;border-radius:50%;background:rgba(0,0,0,.7);color:#fff;cursor:pointer;line-height:1;">×</button></div>`).join('');
      $('#sa-photos').querySelectorAll('[data-prm]').forEach(b => b.onclick = () => { photos.splice(+b.dataset.prm, 1); renderPhotos(); validate(); });
    };
    $('#sa-photo-input').onchange = async (e) => {
      const f = e.target.files && e.target.files[0]; e.target.value = ''; if (!f) return;
      $('#sa-photo-status').textContent = '⏳ Илгээж байна...'; $('#sa-photo-status').style.color = 'var(--muted)';
      try { const url = await uploadReceipt(f, o.id, 'completion', `Захиалга #${o.number} ${act.label}`); if (url) { photos.push(url); renderPhotos(); $('#sa-photo-status').textContent = `✓ ${photos.length} зураг`; $('#sa-photo-status').style.color = 'var(--ok)'; validate(); } else { $('#sa-photo-status').textContent = '⚠ Хадгалж чадсангүй'; $('#sa-photo-status').style.color = 'var(--danger)'; } }
      catch (err) { $('#sa-photo-status').textContent = '⚠ ' + err.message; $('#sa-photo-status').style.color = 'var(--danger)'; }
    };
  }
  if (q) {
    const paint = () => $('#sa-stars').querySelectorAll('[data-star]').forEach(sp => { sp.style.color = (+sp.dataset.star <= rating) ? '#f5a623' : 'var(--border-strong)'; });
    $('#sa-stars').querySelectorAll('[data-star]').forEach(sp => sp.onclick = () => { rating = +sp.dataset.star; paint(); validate(); });
  }
  $('#sa-submit').onclick = async () => {
    $('#sa-submit').disabled = true;
    const sm2 = JSON.parse(JSON.stringify((o.stage_meta && typeof o.stage_meta === 'object') ? o.stage_meta : {}));
    const nowD = new Date().toISOString();
    const entry = Object.assign({}, sm2[act.key], { by: state.me, at: nowD });
    if (needPhoto) entry.photos = photos.slice();
    if (q && rating > 0) { entry.rating = rating; entry.comment = ($('#sa-comment').value || '').trim(); entry.q = q; }
    sm2[act.key] = entry;
    close();
    await bqUpdateStatus(oid, to, { stageMeta: sm2, toast: `${(BQ_STATUS[to] || {}).label || act.label} ✓` });
  };
}
// Badge — цэг + бараан текст (өнгөнд бус, текст+цэгээр ялгана). pill хэлбэр.
function bqStatusBadge(raw) {
  const s = BQ_STATUS[raw] || { label: raw || '—', dot: '#9CA3AF', bg: '#F3F4F6', tx: '#374151' };
  return `<span class="bq-badge" style="display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:999px;font-size:11px;font-weight:600;line-height:1.7;background:${s.bg};color:${s.tx};white-space:nowrap;">
    <span style="width:6px;height:6px;border-radius:50%;flex:0 0 auto;background:${s.dot};"></span>${escapeHtml(s.label)}</span>`;
}
// M-Event төлвийг 6 төлвийн аль нэгэнд буулгана (нэгдсэн шүүлтэд)
function meStatusKey(st) {
  if (st === 'Цуцалсан') return 'canceled';
  if (st === 'Дууссан') return 'stopped';
  if (st === 'Шинэ') return 'reserved';
  return 'started';   // Төлбөр авсан/Цэвэрлэгээ/Түрээс бэлдсэн/Гаргасан/Хүргэсэн/Буцаан ирсэн
}

// Захиалгын жагсаалт — түүхэн нь цорын ганц эх (M-Event давхарга 2026-06-28-нд цуцлагдсан).
// ── App-д үүсгэсэн захиалга (app_orders — түүхэн түүхээс ТУСДАА, refresh устгахгүй) ──
// 2 шаттай ачаалалт: ИДЭВХТЭЙ (~50 мөр) түрүүлж → шууд харагдана; АРХИВ/ЦУЦАЛСАН
// түүх (~1300 мөр, датаны 95%) арын фонд НЭГ л удаа. Poll бүрд зөвхөн идэвхтэйг
// шинэчилнэ — өмнө нь 1.7MB-ийг бүтнээр нь татдаг байсан (утсанд хэдэн секунд).
const _ARCHIVE_STATUSES = ['archived', 'canceled'];
async function loadAppOrders() {
  // Давхар дуудлагыг нэгтгэнэ (view нээх + poll хоёул зэрэг дуудахад НЭГ л fetch явна)
  if (state._ordersInflight) return state._ordersInflight;
  state._ordersInflight = _loadAppOrdersImpl();
  try { return await state._ordersInflight; } finally { state._ordersInflight = null; }
}
async function _loadAppOrdersImpl() {
  if (!DB_ANON_KEY) { state.appOrders = state.appOrders || []; return; }
  // КЭШ-ТҮРҮҮЛЖ ЗУРАХ: өмнөх сессийн идэвхтэй захиалгыг localStorage-оос шууд гаргана
  // (даалгаврын cache-first загвартай ижил) — сүлжээ иртэл хоосон "Ачаалж байна" харагдахгүй.
  if (!(state.appOrders || []).length && !state._ordersCacheSeeded) {
    state._ordersCacheSeeded = true;
    try {
      const c = localStorage.getItem('appOrdersActive');
      if (c) { state.appOrders = JSON.parse(c); if (typeof render === 'function') render(); }
    } catch (e) {}
  }
  const H = { headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + DB_ANON_KEY } };
  const isArch = (o) => _ARCHIVE_STATUSES.includes(String(o.status));
  try {
    // 1-р шат: идэвхтэй захиалгууд — жижиг, хурдан
    const r = await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders?select=*&status=not.in.(archived,canceled)&order=number.desc.nullslast`, H, 20000);
    if (r.ok) {
      const active = await r.json();
      const archive = (state.appOrders || []).filter(isArch);   // санах ойд буй архивыг хадгална
      state.appOrders = active.concat(archive);
      try { localStorage.setItem('appOrdersActive', JSON.stringify(active)); } catch (e) {}   // дараагийн нээлтэд шууд зурна
      if (typeof render === 'function') render();
    }
  } catch (e) { console.warn('loadAppOrders active', e); }
  state.appOrders = state.appOrders || [];
  autoCleanExpiredOrders();   // хугацаа хэтэрсэн биелээгүй захиалгыг авто устгах (сессэд нэг удаа)
  autoFillOrderCompany();     // банкны баримтын төлөгчөөс байгууллагын нэрийг авто бүртгэх (хоосон бол)
  loadUsedReceipts();   // нэгдсэн баримтын ledger (давхцал шалгах)
  // 2-р шат: архив/цуцалсан түүх — сессэд нэг л удаа (ховор өөрчлөгдөнө; аппын үйлдэл optimistic)
  if (!state._archiveLoaded && !state._archiveLoading) {
    state._archiveLoading = true;
    try {
      const r2 = await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders?select=*&status=in.(archived,canceled)&order=number.desc.nullslast`, H, 30000);
      if (r2.ok) {
        const archive = await r2.json();
        const active = (state.appOrders || []).filter(o => !isArch(o));
        state.appOrders = active.concat(archive);
        state._archiveLoaded = true;
        if (typeof render === 'function') render();
      }
    } catch (e) { console.warn('loadAppOrders archive', e); }
    state._archiveLoading = false;
  }
}
// Хугацаа хэтэрсэн захиалгыг "Устгасан" төлөв рүү АВТО зөөх (устгахгүй — "Устгасан" хэсэгт харагдана).
// Нөхцөл: эвентийн огноо ӨНГӨРСӨН + биелээгүй (draft/reserved) + ТӨЛБӨРГҮЙ.
// Төлбөр төлсөн = жинхэнэ захиалга → ХӨНДӨХГҮЙ (зөвхөн гараар цуцлана). Сессэд нэг л удаа.
async function autoCleanExpiredOrders() {
  if (state._expiredCleaned) return;
  state._expiredCleaned = true;
  const t = new Date();
  const today = `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, '0')}-${String(t.getDate()).padStart(2, '0')}`;
  const dead = (state.appOrders || []).filter(o => {
    const st = String(o.status || 'reserved');
    if (st !== 'draft' && st !== 'reserved') return false;   // зөвхөн биелээгүй эрт төлөв
    const end = String(o.stops_at || o.starts_at || '').slice(0, 10);
    if (!end || end >= today) return false;                  // огноогүй / ирээдүй / өнөөдөр → үлдээ
    return (Number(o.paid_mnt) || 0) <= 0;                    // төлбөртэй бол ХӨНДӨХГҮЙ
  });
  if (!dead.length) return;
  dead.forEach(o => { o.status = 'deleted'; });               // optimistic — "Устгасан" төлөв
  if (typeof render === 'function') render();
  for (const o of dead) { try { await saveAppOrder(o); } catch (e) { console.warn('autoClean move', e); } }
  if (typeof showToast === 'function') showToast(`🗑 Хугацаа хэтэрсэн ${dead.length} төлбөргүй захиалгыг "Устгасан" руу шилжүүлэв`, 'info', 4500);
}
// Байгууллагын нэр + РД-г захиалгад авто бүртгэх (⟦CI⟧ note token). Эх сурвалж:
//   1) НӨАТ (ebarimt) баримт — buyer_name + buyer_reg (ХАМГИЙН ЗӨВ: нэр БА регистр).
//   2) банкны баримтын төлөгч — зөвхөн нэр (харилцагчаас ӨӨР бол = байгууллага төлсөн).
// Зөвхөн ХООСОН талбарыг бөглөнө (байгааг хөндөхгүй). Сессэд нэг л удаа.
async function autoFillOrderCompany() {
  if (state._companyFilled) return;
  state._companyFilled = true;
  if (typeof loadVatReceipts === 'function' && !Array.isArray(state.vatReceipts)) { try { await loadVatReceipts(); } catch (e) {} }
  const vatByOrder = {};
  (state.vatReceipts || []).forEach(v => { if (v.matched_id && (v.buyer_name || v.buyer_reg)) { const k = String(v.matched_id); if (!vatByOrder[k]) vatByOrder[k] = v; } });
  let n = 0;
  for (const o of (state.appOrders || [])) {
    const ci = custInfoOf(o.note);
    if (ci.company && ci.reg) continue;                       // хоёулаа бий → алгас
    let company = ci.company || '', reg = ci.reg || '';
    const vr = vatByOrder[String(o.number)];                  // 1) НӨАТ баримт (нэр+РД)
    if (vr) { if (!company && vr.buyer_name) company = String(vr.buyer_name).trim(); if (!reg && vr.buyer_reg) reg = String(vr.buyer_reg).trim(); }
    if (!company) {                                            // 2) банкны төлөгч (зөвхөн нэр)
      const rc = parsePaidRef(o.paid_ref)[0]; const payer = rc && rc.sender ? String(rc.sender).trim() : '';
      if (payer && payer.toLowerCase() !== String(o.customer || '').trim().toLowerCase()) company = payer;
    }
    if ((company && company !== (ci.company || '')) || (reg && reg !== (ci.reg || ''))) {
      ci.company = company || ci.company; ci.reg = reg || ci.reg;
      o.note = setCustInfo(o.note, ci);
      try { await saveAppOrder(o); n++; } catch (e) { console.warn('company fill', e); }
    }
  }
  if (n && typeof showToast === 'function') showToast(`🏢 ${n} захиалгад байгууллага/РД автоматаар бүртгэв`, 'info', 4000);
}
// Дараагийн захиалгын дугаар (түүхэн + app дотроос хамгийн их + 1)
function nextOrderNumber() {
  let mx = 0;
  (state.bqOrders || []).forEach(o => { const n = Number(o.number) || 0; if (n > mx) mx = n; });
  (state.appOrders || []).forEach(o => { const n = Number(o.number) || 0; if (n > mx) mx = n; });
  return mx + 1;
}
// Дараагийн гэрээний дугаар ME-YYYY-NNNN
function nextContractNo() {
  const yr = new Date().getFullYear(); const re = new RegExp('^ME-' + yr + '-(\\d+)$'); let mx = 0;
  (state.appOrders || []).forEach(o => { const m = String(o.contract_no || '').match(re); if (m) mx = Math.max(mx, +m[1]); });
  return `ME-${yr}-${String(mx + 1).padStart(4, '0')}`;
}
// App захиалга хадгалах (UPSERT). Optimistic.
async function saveAppOrder(ord) {
  state.appOrders = state.appOrders || [];
  const idx = state.appOrders.findIndex(o => o.id === ord.id);
  const prev = idx >= 0 ? state.appOrders[idx] : null;   // буцаахад хэрэгтэй хуучин утга
  if (idx >= 0) state.appOrders[idx] = ord; else state.appOrders.unshift(ord);
  if (typeof render === 'function') render();
  if (!DB_ANON_KEY) return;
  let r;
  try {
    r = await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders`, {
      method: 'POST',
      headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' },
      body: JSON.stringify(ord),
    }, 20000);
  } catch (e) { r = null; }
  if (!r || !r.ok) {
    // Серверт хадгалагдсангүй — локал optimistic өөрчлөлтийг БУЦААНА (хуулбар "хадгалагдсан" мэт харагдахаас сэргийлнэ)
    const i2 = state.appOrders.findIndex(o => o.id === ord.id);
    if (prev) { if (i2 >= 0) state.appOrders[i2] = prev; } else { if (i2 >= 0) state.appOrders.splice(i2, 1); }
    if (typeof render === 'function') render();
    const msg = r ? ('Хадгалах алдаа: ' + (await r.text()).slice(0, 80)) : 'Сүлжээ/сервер алдаа — хадгалагдсангүй';
    showToast(msg, 'error', 5000);
    throw new Error('save fail');
  }
}
// Тест захиалга цэвэрлэх (ЗӨВХӨН CEO) — нэрэнд test/тест/demo орсныг сонгож бүрмөсөн устгана
const _TEST_ORDER_RE = /\btest\b|тест|demo|туршил|жишээ|sample/i;
function openTestCleanupModal() {
  if (!state.isCEO) { showToast('Зөвхөн CEO энэ үйлдлийг хийнэ', 'warn', 3000); return; }
  const cands = (state.appOrders || []).filter(o => _TEST_ORDER_RE.test(o.customer || ''));
  const modal = document.createElement('div');
  modal.className = 'modal-bg open'; modal.style.zIndex = '9600';
  modal.innerHTML = `<div class="modal" style="max-width:480px;width:96%;max-height:88vh;overflow:auto;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><h2 style="margin:0;font-size:16px;">🧪 Тест захиалга устгах</h2><button class="btn" id="tc-close" style="padding:5px 10px;">✕</button></div>
    <div style="font-size:12px;color:var(--muted);margin-bottom:10px;">Нэрэнд «test / тест / demo» орсон захиалгууд. Устгавал БҮРМӨСӨН арилна (буцаах боломжгүй).</div>
    ${cands.length ? `<div id="tc-list">${cands.map(o => `<label style="display:flex;align-items:center;gap:9px;padding:7px 4px;border-bottom:1px solid var(--border);font-size:13px;cursor:pointer;">
      <input type="checkbox" class="tc-cb" data-id="${escapeHtml(String(o.id))}" checked style="width:auto;margin:0;">
      <b>#${o.number ?? '—'}</b>
      <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(o.customer || '?')}</span>
      <span style="color:var(--muted);font-size:11px;">${escapeHtml((BQ_STATUS[o.status] || {}).label || o.status || '')}</span>
      <b style="font-variant-numeric:tabular-nums;">${fmtMoney(o.total_mnt || 0)}</b>
    </label>`).join('')}</div>
    <div class="modal-actions" style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
      <button class="btn" id="tc-cancel">Болих</button>
      <button class="btn" id="tc-del" style="background:var(--danger);color:#fff;border-color:var(--danger);">🗑 Устгах (<span id="tc-n">${cands.length}</span>)</button>
    </div>` : `<div style="text-align:center;color:var(--muted);padding:24px;">Тест захиалга олдсонгүй ✓</div>`}
  </div>`;
  document.body.appendChild(modal);
  const close = () => modal.remove();
  modal.querySelector('#tc-close').onclick = close;
  modal.querySelector('#tc-cancel')?.addEventListener('click', close);
  modal.addEventListener('click', e => { if (e.target === modal) close(); });
  const updateN = () => { const el = modal.querySelector('#tc-n'); if (el) el.textContent = modal.querySelectorAll('.tc-cb:checked').length; };
  modal.querySelectorAll('.tc-cb').forEach(cb => cb.addEventListener('change', updateN));
  modal.querySelector('#tc-del')?.addEventListener('click', async (e) => {
    const ids = [...modal.querySelectorAll('.tc-cb:checked')].map(cb => cb.dataset.id);
    if (!ids.length) { showToast('Захиалга сонгоно уу', 'warn'); return; }
    if (!(await showConfirm(`${ids.length} тест захиалгыг БҮРМӨСӨН устгах уу?`, { okText: 'Устгах', danger: true }))) return;
    e.currentTarget.disabled = true;
    let ok = 0;
    for (const id of ids) { try { await deleteAppOrder(id); ok++; } catch (err) { console.warn('test del', err); } }
    close();
    showToast(`${ok} тест захиалга устгалаа`, 'success', 2800);
    if (typeof render === 'function') render();
  });
}
// CEO бөөн үйлдэл — сонгосон захиалгыг устгах/сэргээх (PostgREST id=in.() багцаар)
async function bulkDeleteOrders(ids) {
  const idSet = new Set(ids.map(String));
  const removed = (state.appOrders || []).filter(o => idSet.has(String(o.id)));   // сэргээхэд хэрэгтэй
  state.appOrders = (state.appOrders || []).filter(o => !idSet.has(String(o.id)));
  if (typeof render === 'function') render();
  if (!DB_ANON_KEY) return;
  let failed = false;
  for (let i = 0; i < ids.length; i += 80) {
    const inList = ids.slice(i, i + 80).map(id => '"' + String(id).replace(/["\\]/g, '') + '"').join(',');
    try {
      const r = await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders?id=in.(${encodeURIComponent(inList)})`,
        { method: 'DELETE', headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), Prefer: 'return=minimal' } }, 30000);
      if (!r.ok) failed = true;
    } catch (e) { console.warn('bulkDelete', e); failed = true; }
  }
  if (failed) {
    // Сервер талд устгагдсангүй — UI-аас алга болсон захиалгуудыг БУЦААНА (жинхэнэ дата хэвээр байгааг зөв харуулна)
    const have = new Set((state.appOrders || []).map(o => String(o.id)));
    removed.forEach(o => { if (!have.has(String(o.id))) state.appOrders.push(o); });
    if (typeof render === 'function') render();
    showToast('⚠ Устгал серверт бүрэн хийгдсэнгүй — захиалгыг сэргээлээ, дахин оролдоно уу', 'error', 6000);
    throw new Error('bulkDelete fail');
  }
}
async function bulkRestoreOrders(ids) {
  const idSet = new Set(ids.map(String));
  (state.appOrders || []).forEach(o => { if (idSet.has(String(o.id))) o.status = 'reserved'; });
  if (typeof render === 'function') render();
  if (!DB_ANON_KEY) return;
  for (let i = 0; i < ids.length; i += 80) {
    const inList = ids.slice(i, i + 80).map(id => '"' + String(id).replace(/["\\]/g, '') + '"').join(',');
    try {
      await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders?id=in.(${encodeURIComponent(inList)})`,
        { method: 'PATCH', headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), 'Content-Type': 'application/json', Prefer: 'return=minimal' }, body: JSON.stringify({ status: 'reserved', updated_at: new Date().toISOString() }) }, 30000);
    } catch (e) { console.warn('bulkRestore', e); }
  }
}
async function deleteAppOrder(id) {
  state.appOrders = (state.appOrders || []).filter(o => o.id !== id);
  if (typeof render === 'function') render();
  if (!DB_ANON_KEY) return;
  try { await fetchWithTimeout(`${DB_URL}/rest/v1/app_orders?id=eq.${encodeURIComponent(id)}`, { method: 'DELETE', headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), Prefer: 'return=minimal' } }, 15000); } catch (e) { console.warn('deleteAppOrder', e); }
}
function unifiedOrders() {
  // Захиалга бүр app_orders-т нэгдсэн (түүхэн архив + шинэ захиалга). Нэг эх сурвалж.
  // source='history' → түүхэн, source='app' → шинэ; аль аль нь адилхан app_orders мөр.
  return (state.appOrders || []).map(ao => {
    // Canon төлөв — нэг helper (orderCanonStatus). Нөөц тооцоо (bookedQtyForRange) болон багц сонголт
    // мөн ижил helper ашигладаг тул харагдац ↔ логик зөрөхгүй (төлбөргүй reserved→'draft' г.м.).
    const raw = orderCanonStatus(ao);
    const o = { ...ao, status: raw, item_count: (ao.items || []).length, _app: true };
    return { src: 'app', o, status: raw, skey: BQ_STATUS[raw] ? raw : 'reserved',
      ym: String(ao.starts_at || ao.created_at || '').slice(0, 7), date: ao.starts_at || ao.created_at || '',
      total: Number(ao.total_mnt) || 0,
      hay: `#${ao.number ?? ''} ${ao.customer || ''} ${ao.phone || ''} ${ao.contract_no || ''}`.toLowerCase() };
  });
}

// Түрээсийн хоног: 24ц = 1 хоног, 24ц-аас хэтэрвэл +1 хоног (минут тоохгүй, зөвхөн цагаар). Доод тал 1 хоног.
function rentalDays(startMs, stopMs) {
  const h = (stopMs - startMs) / 3600000;
  if (!(h > 0)) return 1;
  return Math.max(1, Math.ceil(h / 24));
}
// Эхлэх/дуусах ЦАГ-ийг note token-оор хадгална (app_orders-д timestamptz багана нэмэхгүйгээр; codebase-ийн ⟦…⟧ загвартай нийцнэ).
const _RT_RE = /⟦RT\|(\d{1,2})\|(\d{1,2})⟧/;
function parseOrderTimes(note) { const m = String(note || '').match(_RT_RE); return m ? { sh: +m[1], eh: +m[2] } : null; }
function encodeOrderTimes(sh, eh) { return `⟦RT|${sh}|${eh}⟧`; }
function cleanAppNote(note) { return String(note || '').replace(/⟦[A-Z]{2,4}\|[^⟧]*⟧/g, '').trim(); }   // бүх ⟦XX…|…⟧ token-ийг арилгана (RT, SL, DLV, CX г.м.)
// Цуцлах/устгах шалтгаан — note-д ⟦CX|шалтгаан⟧ token-оор (app_orders-д багана нэмэхгүйгээр). cleanAppNote нуудаг.
const _CX_RE = /⟦CX\|([^⟧]*)⟧/;
function cancelReasonOf(note) { const m = String(note || '').match(_CX_RE); return m ? m[1].trim() : ''; }
function setCancelReason(note, reason) {
  const base = String(note || '').replace(_CX_RE, '').replace(_CXRQ_RE, '').trim();
  const r = String(reason || '').replace(/[⟦⟧|]/g, ' ').replace(/\s+/g, ' ').trim();
  return (base ? base + ' ' : '') + `⟦CX|${r}⟧`;
}
// Цуцлах ХҮСЭЛТ (менежер илгээнэ, CEO батална) — ⟦CXRQ|хэн|огноо|шалтгаан⟧ (4 үсэг тул cleanAppNote нуудаг)
const _CXRQ_RE = /⟦CXRQ\|([^|⟧]*)\|([^|⟧]*)\|([^⟧]*)⟧/;
function cancelReqOf(note) { const m = String(note || '').match(_CXRQ_RE); return m ? { by: m[1], date: m[2], reason: m[3].trim() } : null; }
function setCancelReq(note, by, date, reason) {
  const base = String(note || '').replace(_CXRQ_RE, '').trim();
  const r = String(reason || '').replace(/[⟦⟧|]/g, ' ').replace(/\s+/g, ' ').trim();
  return (base ? base + ' ' : '') + `⟦CXRQ|${by}|${date}|${r}⟧`;
}
function clearCancelReq(note) { return String(note || '').replace(_CXRQ_RE, '').replace(/\s{2,}/g, ' ').trim(); }
// Захиалгын note-г шинэчлэх (статус хөндөхгүй) — app_orders/bq_orders routing
async function patchOrderNote(oid, note) {
  let o = (state.bqOrders || []).find(x => String(x.id) === String(oid)); const table = o ? 'bq_orders' : 'app_orders';
  const r = await fetchWithTimeout(`${DB_URL}/rest/v1/${table}?id=eq.${encodeURIComponent(oid)}`, { method: 'PATCH', headers: { apikey: DB_ANON_KEY, Authorization: 'Bearer ' + pgrstBearer(), 'Content-Type': 'application/json', Prefer: 'return=minimal' }, body: JSON.stringify({ note, updated_at: new Date().toISOString() }) }, 15000);
  if (!r.ok) throw new Error('HTTP ' + r.status);
}
// Менежер — цуцлах хүсэлт илгээх (заавал шалтгаантай, CEO батална)
async function requestOrderCancel(oid) {
  const o = (state.appOrders || []).find(x => String(x.id) === String(oid)) || (state.bqOrders || []).find(x => String(x.id) === String(oid));
  if (!o) return;
  const reason = await showPrompt(`#${o.number ?? ''} захиалгыг цуцлах шалтгаанаа бичнэ үү. Хүсэлт CEO-д батлуулахаар илгээгдэнэ:`, { title: '✕ Цуцлах хүсэлт', okText: 'Хүсэлт илгээх', placeholder: 'Ж: харилцагч больсон, давхардсан…' });
  if (reason == null) return;
  if (!reason.trim()) { showToast('Шалтгаанаа бичнэ үү', 'warn', 2500); return; }
  const note = setCancelReq(o.note, state.me, new Date().toISOString().slice(0, 10), reason.trim());
  const prev = o.note; o.note = note; render();
  try { await patchOrderNote(oid, note); showToast('Цуцлах хүсэлт CEO-д илгээгдлээ', 'success', 2500); }
  catch (e) { o.note = prev; render(); showToast('Хүсэлт илгээх алдаа: ' + e.message, 'error', 4000); }
}
// CEO — цуцлах хүсэлтийг батлах (→ цуцлагдана) эсвэл татгалзах
async function approveOrderCancel(oid) {
  if (!state.isCEO) { showToast('Зөвхөн захирал батална', 'warn', 3000); return; }
  const o = (state.appOrders || []).find(x => String(x.id) === String(oid)) || (state.bqOrders || []).find(x => String(x.id) === String(oid));
  if (!o) return; const req = cancelReqOf(o.note);
  if (!(await showConfirm(`#${o.number ?? ''} цуцлахыг батлах уу?\n\nШалтгаан: ${req ? req.reason : '—'}`, { okText: 'Батлах', danger: true }))) return;
  o.note = clearCancelReq(o.note);   // хүсэлтийн token-г арилгаад
  bqUpdateStatus(oid, 'canceled', { reason: (req && req.reason) || 'CEO баталсан', toast: 'Цуцлахыг баталлаа' });
}
async function rejectOrderCancel(oid) {
  if (!state.isCEO) { showToast('Зөвхөн захирал шийднэ', 'warn', 3000); return; }
  const o = (state.appOrders || []).find(x => String(x.id) === String(oid)) || (state.bqOrders || []).find(x => String(x.id) === String(oid));
  if (!o) return;
  if (!(await showConfirm(`#${o.number ?? ''} цуцлах хүсэлтийг татгалзах уу? Захиалга хэвээр үлдэнэ.`, { okText: 'Татгалзах' }))) return;
  const prev = o.note; o.note = clearCancelReq(o.note); render();
  try { await patchOrderNote(oid, o.note); showToast('Цуцлах хүсэлтийг татгалзлаа', 'success', 2500); }
  catch (e) { o.note = prev; render(); showToast('Алдаа: ' + e.message, 'error', 4000); }
}

// ── Хүргэлтийн төлбөр — байршлаар автомат (сайт+апп нэг томьёо) ──
// Хот дотор = тогтмол (очих+буцах багтсан). Хотоос гадна = нэг талын км × 2 (очих+буцах) × км-ийн үнэ.
const DELIVERY_CITY_FEE = 150000;   // ₮ хот дотор
const DELIVERY_PER_KM = 5000;       // ₮ нэг талын км тутам
function calcDeliveryFee(zone, km) {
  if (zone === 'city') return DELIVERY_CITY_FEE;
  if (zone === 'out') return Math.max(0, (Math.round(Number(km) || 0)) * 2 * DELIVERY_PER_KM);
  return 0;   // pickup / хоосон
}
